INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0001', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'pattern_discovery', 'Explore', 'easy', 'multiple_choice', 'Find the next number: 1, 2, 4, 7, 11, 16, ___?', '[{"id": "A", "text": "20"}, {"id": "B", "text": "21"}, {"id": "C", "text": "22"}, {"id": "D", "text": "23"}]'::jsonb, 'C', 'Gaps: +1, +2, +3, +4, +5. Each gap grows by 1, so the next gap is +6: 16 + 6 = 22.', 'Spotting a changing (second-order) difference.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0002', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'pattern_discovery', 'Think', 'medium', 'multiple_choice', 'Find the next number: 3, 6, 5, 12, 7, 24, 9, ___?', '[{"id": "A", "text": "36"}, {"id": "B", "text": "48"}, {"id": "C", "text": "40"}, {"id": "D", "text": "52"}]'::jsonb, 'B', 'Two woven sequences. Odd positions: 3, 5, 7, 9 (+2). Even positions: 6, 12, 24 (x2). The missing 8th term is the next even-position term: 24 x 2 = 48.', 'Splitting two interleaved sequences.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0034', 'logical_reasoning', 'Logical Thinking', '2.1', 'deductive_ordering', 'Explore', 'easy', 'multiple_choice', 'Tom is taller than Sam. Sam is taller than Lee. Who is the shortest?', '[{"id": "A", "text": "Tom"}, {"id": "B", "text": "Sam"}, {"id": "C", "text": "Lee"}, {"id": "D", "text": "Cannot tell"}]'::jsonb, 'C', 'Taller order: Tom > Sam > Lee, so Lee is shortest.', 'Building a linear order from two transitive clues.', ARRAY['p3','high_ability','logical','ordering'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0007', 'logical_reasoning', 'Logical Thinking', '2.1', 'deductive_ordering', 'Think', 'medium', 'multiple_choice', 'Four teams race. Red finishes before Blue. Green finishes after Yellow. Blue finishes before Green. Yellow finishes before Red. Order them from fastest to slowest.', '[{"id": "A", "text": "Yellow, Red, Blue, Green"}, {"id": "B", "text": "Red, Blue, Green, Yellow"}, {"id": "C", "text": "Yellow, Blue, Red, Green"}, {"id": "D", "text": "Green, Yellow, Red, Blue"}]'::jsonb, 'A', 'From the clues: Yellow < Red < Blue (Yellow before Red, Red before Blue). Also Blue < Green and Yellow < Green. Together: Yellow < Red < Blue < Green. Fastest to slowest: Yellow, Red, Blue, Green.', 'Merging two partial orderings into one total order.', ARRAY['p3','high_ability','logical','ordering'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0036', 'logical_reasoning', 'Logical Thinking', '2.4', 'classification_sets', 'Explore', 'easy', 'multiple_choice', 'Which is the odd one out? A red square   B red triangle   C blue square   D red square', '[{"id": "A", "text": "A"}, {"id": "B", "text": "B"}, {"id": "C", "text": "C"}, {"id": "D", "text": "D"}]'::jsonb, 'C', 'Three of the four are red (A, B, D). C is the only blue one, so by the majority property (colour) C is the odd one out. Shape alone is a trap (B is the only triangle).', 'Finding the property that three share (majority dimension).', ARRAY['p3','high_ability','logical','classification'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0010', 'logical_reasoning', 'Logical Thinking', '2.4', 'classification_sets', 'Think', 'medium', 'multiple_choice', 'Four figures: A red square, B red square, C red square, D blue square. Which does not belong, and why?', '[{"id": "A", "text": "A (it is a square)"}, {"id": "B", "text": "B (it is red)"}, {"id": "C", "text": "D (it is the only blue one)"}, {"id": "D", "text": "C (it is the only triangle)"}]'::jsonb, 'C', 'Three figures share BOTH shape (square) and colour (red). D is also a square but is blue, so the distinguishing dimension is colour: D is the odd one. Option D is a trap (there is no triangle).', 'Attending to two dimensions to find the true odd-one-out.', ARRAY['p3','high_ability','logical','classification'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0011', 'logical_reasoning', 'Logical Thinking', '2.5', 'syllogisms', 'Challenge', 'hard', 'multiple_choice', 'All squares are blue. All blue things are small. Which MUST be true?', '[{"id": "A", "text": "All squares are small"}, {"id": "B", "text": "All small things are squares"}, {"id": "C", "text": "All blue things are squares"}, {"id": "D", "text": "All squares are heavy"}]'::jsonb, 'A', 'Every square is blue, and everything blue is small, so every square is small. The others reverse the direction of the rules and need not be true.', 'Chaining set inclusions (transitive).', ARRAY['p3','high_ability','logical','challenge'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0016', 'verbal_reasoning', 'Verbal Reasoning', '3.5', 'sentence_logic', 'Think', 'medium', 'multiple_choice', 'Mei reads every Saturday. She also reads whenever it rains. Today she is NOT reading. What MUST be true?', '[{"id": "A", "text": "It is not Saturday and not raining"}, {"id": "B", "text": "It is Saturday"}, {"id": "C", "text": "It is raining"}, {"id": "D", "text": "Mei is sleeping"}]'::jsonb, 'A', 'She reads if Saturday OR raining. Today she does NOT read, so neither condition holds: it is not Saturday and it is not raining. B and C would make her read; D adds info we are not given.', 'Must-be-true from the negation of a combined condition (contrapositive of an OR).', ARRAY['p3','high_ability','verbal','logic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0039', 'visual_spatial', 'Visual & Spatial', '4.1', 'single_rotation', 'Explore', 'easy', 'multiple_choice', 'An L-shape has its corner at the top-left. It is rotated 90 degrees clockwise. Where is the corner now?', '[{"id": "A", "text": "top-left"}, {"id": "B", "text": "top-right"}, {"id": "C", "text": "bottom-right"}, {"id": "D", "text": "bottom-left"}]'::jsonb, 'B', 'Rotating 90 degrees clockwise moves the top-left corner to the top-right corner. Because the shape is asymmetric (an L), the orientation actually matters.', 'Mentally rotating an asymmetric shape.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "single_rotation", "shape": "L", "mark": "corner_top_left", "rotation": "clockwise 90", "result": "corner_top_right"}'::jsonb, 'p3/BA_P3_0039.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0017', 'visual_spatial', 'Visual & Spatial', '4.1', 'single_rotation', 'Think', 'medium', 'multiple_choice', 'An arrow points up. It is rotated 90 degrees clockwise, then another 90 degrees clockwise. Which way does it point now?', '[{"id": "A", "text": "up"}, {"id": "B", "text": "right"}, {"id": "C", "text": "down"}, {"id": "D", "text": "left"}]'::jsonb, 'C', 'Up -> right (first turn) -> down (second turn). Two 90-degree clockwise turns = 180 degrees, so the arrow points down.', 'Tracking rotation across two steps.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "rotation_sequence", "shape": "arrow", "start": "up", "rule": "clockwise 90 per step", "steps": 2, "result": "down"}'::jsonb, 'p3/BA_P3_0017.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0018', 'visual_spatial', 'Visual & Spatial', '4.2', 'reflection', 'Think', 'medium', 'multiple_choice', 'The letter ''b'' is reflected in a vertical mirror (left-right flip). Which letter does the reflection look like?', '[{"id": "A", "text": "b"}, {"id": "B", "text": "d"}, {"id": "C", "text": "p"}, {"id": "D", "text": "q"}]'::jsonb, 'B', 'A vertical (left-right) mirror flips ''b'' so its round part moves to the right, making it look like ''d''.', 'Mirror reflection across a vertical axis.', ARRAY['p3','high_ability','spatial','reflection'], true, '{"type": "reflection", "axis": "vertical", "source": "b", "result": "d"}'::jsonb, 'p3/BA_P3_0018.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0019', 'visual_spatial', 'Visual & Spatial', '4.3', 'cube_net', 'Challenge', 'hard', 'multiple_choice', 'A cube net: centre square Y, with W above Y, V below Y, X left of Y, Z right of Y, and U below V (V and U form a column under Y). Folded with Y as the front face, which square is the BACK face (opposite the front)?', '[{"id": "A", "text": "W (above Y)"}, {"id": "B", "text": "V (below Y)"}, {"id": "C", "text": "U (bottom of column)"}, {"id": "D", "text": "Z (right of Y)"}]'::jsonb, 'C', 'Fold Y as front: X=left, Z=right, W=top, V=bottom, and the remaining square U folds to the back. The face opposite front (Y) is the back = U.', 'Folding a net to find the opposite face.', ARRAY['p3','high_ability','spatial','net','challenge'], true, '{"type": "cube_net", "layout": [["", "W", ""], ["X", "Y", "Z"], ["", "V", ""], ["", "U", ""]], "front": "Y", "back": "U"}'::jsonb, 'p3/BA_P3_0019.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0021', 'visual_spatial', 'Visual & Spatial', '4.4', 'rotation_3d', 'Challenge', 'hard', 'multiple_choice', 'A cube has a dot on its TOP face and a star on its FRONT face. You rotate it 90 degrees to the right around the vertical axis. Where is the star now?', '[{"id": "A", "text": "top"}, {"id": "B", "text": "front"}, {"id": "C", "text": "right"}, {"id": "D", "text": "left"}]'::jsonb, 'C', 'Rotating around the vertical axis to the right turns the front face to the right side. The top face (dot) stays on top. The star moves from front to right.', '3D rotation around the vertical axis.', ARRAY['p3','high_ability','spatial','rotation','challenge'], true, '{"type": "rotation_3d", "axis": "vertical", "marks": {"top": "dot", "front": "star"}, "rotation": "right 90", "star_after": "right"}'::jsonb, 'p3/BA_P3_0021.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0020', 'visual_spatial', 'Visual & Spatial', '4.6', 'shape_transformation', 'Explore', 'easy', 'multiple_choice', 'Each step the shape gains one side AND its colour alternates red, blue, red... A red triangle becomes a blue square, then a red pentagon. What comes next?', '[{"id": "A", "text": "hexagon, blue"}, {"id": "B", "text": "hexagon, red"}, {"id": "C", "text": "heptagon, blue"}, {"id": "D", "text": "circle"}]'::jsonb, 'A', 'Two rules: sides go 3,4,5 so next is 6 (hexagon); colour goes red, blue, red, so next is blue. The next shape is a blue hexagon.', 'Continuing a two-feature transformation.', ARRAY['p3','high_ability','spatial','transformation'], true, '{"type": "shape_transformation", "rule": "add one side AND alternate colour red/blue", "sequence": ["triangle red(3)", "square blue(4)", "pentagon red(5)", "hexagon blue(6)"]}'::jsonb, 'p3/BA_P3_0020.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0026', 'pattern_abstract', 'Pattern & Abstract', '5.5', 'count_sequence', 'Explore', 'easy', 'multiple_choice', 'Groups of dots: 2, then 3, then 5, then 8, then 13. How many dots come next?', '[{"id": "A", "text": "18"}, {"id": "B", "text": "20"}, {"id": "C", "text": "21"}, {"id": "D", "text": "26"}]'::jsonb, 'C', 'Each group has as many dots as the two previous groups combined: 2+3=5, 3+5=8, 5+8=13, so 8+13=21.', 'Continuing a sum-of-previous-two progression.', ARRAY['p3','high_ability','pattern','sequence'], true, '{"type": "count_sequence", "counts": [2, 3, 5, 8, 13], "next": 21}'::jsonb, 'p3/BA_P3_0026.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0044', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Explore', 'easy', 'multiple_choice', 'A number plus 5 equals 12. What is the number?', '[{"id": "A", "text": "7"}, {"id": "B", "text": "17"}, {"id": "C", "text": "8"}, {"id": "D", "text": "6"}]'::jsonb, 'A', 'Work backwards: the result was 12, so before adding 5 the number was 12 - 5 = 7.', 'Reversing a single operation.', ARRAY['p3','high_ability','heuristics','working_backwards'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0028', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Think', 'medium', 'multiple_choice', 'A number is doubled, then 3 is added, and the result is 15. What was the starting number?', '[{"id": "A", "text": "5"}, {"id": "B", "text": "6"}, {"id": "C", "text": "7"}, {"id": "D", "text": "9"}]'::jsonb, 'B', 'Work backwards: the result was 15, so before adding 3 it was 12, and before doubling it was 12 / 2 = 6. Starting number = 6.', 'Reversing two operations in the correct order.', ARRAY['p3','high_ability','heuristics','working_backwards'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0045', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Challenge', 'hard', 'multiple_choice', 'A bus had some children. At a stop, 8 got off and 5 got on. Now there are 14 children on the bus. How many were on the bus at first?', '[{"id": "A", "text": "11"}, {"id": "B", "text": "17"}, {"id": "C", "text": "19"}, {"id": "D", "text": "7"}]'::jsonb, 'B', 'Work backwards from 14: before 5 got on there were 14 - 5 = 9; before 8 got off there were 9 + 8 = 17. So 17 at first.', 'Working backwards through a real-world context.', ARRAY['p3','high_ability','heuristics','working_backwards'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0046', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Master', 'expert', 'multiple_choice', 'A number is doubled, then 4 is added, then 5 is subtracted, and the result is 11. What was the starting number? Check your answer by going forward.', '[{"id": "A", "text": "5"}, {"id": "B", "text": "7"}, {"id": "C", "text": "8"}, {"id": "D", "text": "6"}]'::jsonb, 'D', 'Work backwards: 11 + 5 = 16; 16 - 4 = 12; 12 / 2 = 6. Check forward: 6 x 2 = 12, +4 = 16, -5 = 11. Correct, so start = 6.', 'Working backwards through a 3-step process AND verifying with the forward check (combining two heuristics).', ARRAY['p3','high_ability','heuristics','working_backwards','master'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0047', 'problem_solving', 'Problem Solving', '6.2', 'guess_check', 'Explore', 'easy', 'multiple_choice', 'Some coins are 2-dollar and some are 5-dollar. There are 7 coins in total and they make 23 dollars. How many 5-dollar coins are there?', '[{"id": "A", "text": "2"}, {"id": "B", "text": "3"}, {"id": "C", "text": "4"}, {"id": "D", "text": "5"}]'::jsonb, 'B', 'Try 3 five-dollar coins (=15) and 4 two-dollar coins (=8). Total value 23 and total coins 7. That fits, so 3 five-dollar coins. (Systematic guess-&-check across the few cases.)', 'Systematic trial across a few cases.', ARRAY['p3','high_ability','heuristics','guess_check'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0029', 'problem_solving', 'Problem Solving', '6.2', 'guess_check', 'Think', 'medium', 'multiple_choice', 'There are some 2-dollar and 5-dollar coins. There are 6 coins in total and they make 18 dollars. How many 5-dollar coins are there?', '[{"id": "A", "text": "1"}, {"id": "B", "text": "2"}, {"id": "C", "text": "3"}, {"id": "D", "text": "4"}]'::jsonb, 'B', 'Try 2 five-dollar coins (=10) and 4 two-dollar coins (=8). Total value 18 and total coins 6. That fits, so there are 2 five-dollar coins.', 'Guess-&-check across more combinations, systematically.', ARRAY['p3','high_ability','heuristics','guess_check'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_V01', 'verbal_reasoning', 'Verbal Reasoning', '3.1', 'word_analogy', 'Think', 'medium', 'multiple_choice', 'Leaf is to tree as page is to ___?', '[{"id": "A", "text": "book"}, {"id": "B", "text": "paper"}, {"id": "C", "text": "word"}, {"id": "D", "text": "cover"}]'::jsonb, 'A', 'Relation: a single part that, together with many others, makes up the whole. A leaf is one part of a tree; a page is one part of a book. (Paper is made from trees; word is what is printed on a page; cover is one part of a book but not the ''many parts make the whole'' part.)', 'Finding a part-whole relation and applying it to a new pair.', ARRAY['p3','high_ability','verbal','analogy'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_V02', 'verbal_reasoning', 'Verbal Reasoning', '3.1', 'word_analogy', 'Challenge', 'hard', 'multiple_choice', 'Cup, plate, bowl : rose, tulip, sunflower : apple, banana, ___?', '[{"id": "A", "text": "orange"}, {"id": "B", "text": "carrot"}, {"id": "C", "text": "leaf"}, {"id": "D", "text": "tree"}]'::jsonb, 'A', 'The relation is NOT a word pair. Each group is a set of three things in the same category: Group 1 = things you eat from (dishes); Group 2 = flowers; Group 3 = fruits. The missing member of the fruit set is orange. (Carrot is a vegetable, not a fruit; leaf and tree are not fruits.)', 'Discovering that the relation is category-to-category (set correspondence), then completing the last set.', ARRAY['p3','high_ability','verbal','analogy','set'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_V04', 'verbal_reasoning', 'Verbal Reasoning', '3.2', 'word_classification', 'Think', 'medium', 'multiple_choice', 'Which does NOT belong?  A clock  B watch  C timer  D ruler', '[{"id": "A", "text": "clock"}, {"id": "B", "text": "watch"}, {"id": "C", "text": "timer"}, {"id": "D", "text": "ruler"}]'::jsonb, 'D', 'Clock, watch and timer are all things that tell or measure TIME. A ruler measures LENGTH, not time, so it is the odd one out. The grouping is by function, not by how the objects look.', 'Finding a non-obvious shared property (function) and rejecting a surface-feature grouping.', ARRAY['p3','high_ability','verbal','odd_one_out'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_V05', 'verbal_reasoning', 'Verbal Reasoning', '3.3', 'codes_ciphers', 'Think', 'medium', 'multiple_choice', 'In a code, a letter is worth the SQUARE of its place in the alphabet (A=1, B=4, C=9, D=16 ...). Which letter is worth 25?', '[{"id": "A", "text": "E"}, {"id": "B", "text": "Y"}, {"id": "C", "text": "F"}, {"id": "D", "text": "S"}]'::jsonb, 'A', 'The values are squares: 1, 4, 9, 16 ... so 25 = 5 squared. E is the 5th letter of the alphabet, therefore E = 25. (Y is the 25th letter - a near-miss if you match the number to the letter directly; F would be 6; S would be 19.)', 'Discovering the square rule from the examples, then mapping a square root back to a letter position.', ARRAY['p3','high_ability','verbal','cipher'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_V06', 'verbal_reasoning', 'Verbal Reasoning', '3.3', 'codes_ciphers', 'Challenge', 'hard', 'multiple_choice', 'In a code, DOG becomes GLJ and CAT becomes FDW. The rule is: move the 1st letter forward 3, the 2nd letter back 3, the 3rd letter forward 3, and keep alternating. What does PIG become?', '[{"id": "A", "text": "SFJ"}, {"id": "B", "text": "SLJ"}, {"id": "C", "text": "SFD"}, {"id": "D", "text": "MFJ"}]'::jsonb, 'A', 'Apply the alternating rule to PIG: P forward 3 = S; I back 3 = F; G forward 3 = J. So PIG becomes SFJ. (SLJ is if every letter moved forward 3; SFD is if the last letter also moved back; MFJ is if the first moved back.)', 'Inferring an alternating +/- shift rule from two examples, then applying it to a new word.', ARRAY['p3','high_ability','verbal','cipher'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_V07', 'verbal_reasoning', 'Verbal Reasoning', '3.4', 'word_manipulation', 'Think', 'medium', 'multiple_choice', 'In a code, TRAIN becomes RAINT and PLANT becomes LANTP. The rule moves the FIRST letter to the END. What does HOUSE become?', '[{"id": "A", "text": "OUSEH"}, {"id": "B", "text": "HOUSE"}, {"id": "C", "text": "USEHO"}, {"id": "D", "text": "EHOSU"}]'::jsonb, 'A', 'Move the first letter H to the end of HOUSE and you get OUSEH. (USEHO moves the LAST letter to the front; EHOSU reverses the word; HOUSE is unchanged.)', 'Discovering a transformation rule (first letter to end) from two examples, then applying it.', ARRAY['p3','high_ability','verbal','word_manipulation'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_V09', 'verbal_reasoning', 'Verbal Reasoning', '3.5', 'sentence_logic', 'Challenge', 'hard', 'multiple_choice', 'Three boxes are red, blue and green. Each holds one thing: a book, a ball or a coin. (1) The blue box holds the book. (2) The red box does not hold the ball. (3) The green box does not hold the coin. What does the green box hold?', '[{"id": "A", "text": "ball"}, {"id": "B", "text": "book"}, {"id": "C", "text": "coin"}, {"id": "D", "text": "cannot tell"}]'::jsonb, 'A', 'Blue = book, so red and green share ball and coin. Red does NOT hold the ball, so red = coin. That leaves green = ball. Clue (3) is the consistency check: green does not hold the coin - true, so the assignment holds.', 'Combining three constraints to fix a unique assignment (deduction, not guess).', ARRAY['p3','high_ability','verbal','logic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0060', 'logical_reasoning', 'Logical Thinking', '2.1', 'linear_order', 'Explore', 'easy', 'multiple_choice', 'P and Q are taller than R. Q is shorter than P. Order them from tallest to shortest.', '[{"id": "A", "text": "P, Q, R"}, {"id": "B", "text": "Q, P, R"}, {"id": "C", "text": "R, P, Q"}, {"id": "D", "text": "P, R, Q"}]'::jsonb, 'A', 'P is tallest (P > Q and P > R). Q is shorter than P but taller than R, so P > Q > R.', 'Building a linear order from two transitive clues.', ARRAY['p3','high_ability','logical','ordering'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0061', 'logical_reasoning', 'Logical Thinking', '2.1', 'merge_partial_orders', 'Think', 'medium', 'multiple_choice', 'Four runners race. A beats B. B beats C. D beats A. Order them from fastest to slowest.', '[{"id": "A", "text": "D, A, B, C"}, {"id": "B", "text": "A, D, B, C"}, {"id": "C", "text": "D, B, A, C"}, {"id": "D", "text": "A, B, C, D"}]'::jsonb, 'A', 'D beats A, and A beats B, and B beats C, so D > A > B > C. Fastest to slowest: D, A, B, C.', 'Merging two partial orderings into one total order.', ARRAY['p3','high_ability','logical','ordering'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0066', 'logical_reasoning', 'Logical Thinking', '2.4', 'figure_classification', 'Think', 'medium', 'multiple_choice', 'Which shape does NOT belong?  A triangle  B square  C circle  D rectangle', '[{"id": "A", "text": "triangle"}, {"id": "B", "text": "square"}, {"id": "C", "text": "circle"}, {"id": "D", "text": "rectangle"}]'::jsonb, 'C', 'Triangle, square and rectangle are polygons with straight sides. The circle is the only curved shape, so it does not belong.', 'Finding the property three share (straight sides) and the odd one.', ARRAY['p3','high_ability','logical','classification'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0067', 'logical_reasoning', 'Logical Thinking', '2.5', 'syllogism', 'Think', 'medium', 'multiple_choice', 'All cats are animals. All animals are living things. Which MUST be true?', '[{"id": "A", "text": "All cats are living things"}, {"id": "B", "text": "All living things are cats"}, {"id": "C", "text": "All animals are cats"}, {"id": "D", "text": "Cats are not living"}]'::jsonb, 'A', 'Every cat is an animal, and every animal is living, so every cat is living. The others reverse the direction of the rules.', 'Chaining set inclusions (transitive).', ARRAY['p3','high_ability','logical','syllogism'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0068', 'logical_reasoning', 'Logical Thinking', '2.5', 'syllogism_particular', 'Challenge', 'hard', 'multiple_choice', 'Some squares are red. All red things are small. Which MUST be true?', '[{"id": "A", "text": "Some squares are small"}, {"id": "B", "text": "All squares are small"}, {"id": "C", "text": "All small things are squares"}, {"id": "D", "text": "No squares are small"}]'::jsonb, 'A', 'The red squares are squares AND red; all red things are small, so those squares are small. Thus SOME squares are small. ''All squares are small'' need not be true.', 'Chaining a particular quantifier with a universal one without over-generalising.', ARRAY['p3','high_ability','logical','syllogism'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0069', 'visual_spatial', 'Visual & Spatial', '4.1', 'single_rotation', 'Explore', 'easy', 'multiple_choice', 'An arrow points UP. It is rotated 90 degrees clockwise. Which way does it point now?', '[{"id": "A", "text": "right"}, {"id": "B", "text": "down"}, {"id": "C", "text": "left"}, {"id": "D", "text": "up"}]'::jsonb, 'A', 'One 90-degree clockwise turn moves UP to RIGHT.', 'Mentally rotating a shape one step.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "rotation_sequence", "start": "up", "steps": 1}'::jsonb, 'p3/BA_P3_0069.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0070', 'visual_spatial', 'Visual & Spatial', '4.1', 'two_step_rotation', 'Think', 'medium', 'multiple_choice', 'An arrow points UP. It is rotated 90 degrees clockwise twice. Which way does it point now?', '[{"id": "A", "text": "down"}, {"id": "B", "text": "right"}, {"id": "C", "text": "left"}, {"id": "D", "text": "up"}]'::jsonb, 'A', 'Two 90-degree clockwise turns = 180 degrees, so UP becomes DOWN.', 'Tracking rotation across two steps.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "rotation_sequence", "start": "up", "steps": 2}'::jsonb, 'p3/BA_P3_0070.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0071', 'visual_spatial', 'Visual & Spatial', '4.2', 'mirror_reflection', 'Think', 'medium', 'multiple_choice', 'The letter ''p'' is reflected in a vertical mirror (left-right flip). Which letter does the reflection look like?', '[{"id": "A", "text": "q"}, {"id": "B", "text": "p"}, {"id": "C", "text": "b"}, {"id": "D", "text": "d"}]'::jsonb, 'A', 'A vertical (left-right) mirror flips ''p'' so its bowl moves to the left, making it look like ''q''.', 'Mirror reflection across a vertical axis.', ARRAY['p3','high_ability','spatial','reflection'], true, '{"type": "reflection", "axis": "vertical", "source": "p", "result": "q"}'::jsonb, 'p3/BA_P3_0071.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0072', 'visual_spatial', 'Visual & Spatial', '4.2', 'mirror_reflection', 'Think', 'medium', 'multiple_choice', 'The letter ''d'' is reflected in a vertical mirror (left-right flip). Which letter does the reflection look like?', '[{"id": "A", "text": "b"}, {"id": "B", "text": "d"}, {"id": "C", "text": "p"}, {"id": "D", "text": "q"}]'::jsonb, 'A', 'A vertical mirror flips ''d'' so its bowl moves to the left, making it look like ''b''.', 'Mirror reflection across a vertical axis (reverse case).', ARRAY['p3','high_ability','spatial','reflection'], true, '{"type": "reflection", "axis": "vertical", "source": "d", "result": "b"}'::jsonb, 'p3/BA_P3_0072.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0073', 'visual_spatial', 'Visual & Spatial', '4.3', 'cube_net', 'Think', 'medium', 'multiple_choice', 'A cube net: centre square A, with B above A, C below A, D left of A, E right of A, and F below C. Folded with A as the front face, which square is the BACK face (opposite the front)?', '[{"id": "A", "text": "F"}, {"id": "B", "text": "B"}, {"id": "C", "text": "C"}, {"id": "D", "text": "E"}]'::jsonb, 'A', 'Fold A as front: D = left, E = right, B = top, C = bottom, and the remaining square F folds to the back. The face opposite front (A) is the back = F.', 'Folding a net to find the opposite face.', ARRAY['p3','high_ability','spatial','net'], true, '{"type": "cube_net", "layout": [["", "B", ""], ["D", "A", "E"], ["", "C", ""], ["", "F", ""]], "front": "A", "back": "F"}'::jsonb, 'p3/BA_P3_0073.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0074', 'visual_spatial', 'Visual & Spatial', '4.4', 'rotation_3d', 'Challenge', 'hard', 'multiple_choice', 'A cube has a dot on its TOP face and a star on its RIGHT face. You rotate it 90 degrees to the LEFT around the vertical axis. Where is the star now?', '[{"id": "A", "text": "front"}, {"id": "B", "text": "right"}, {"id": "C", "text": "top"}, {"id": "D", "text": "left"}]'::jsonb, 'A', 'Rotating around the vertical axis to the left turns the right face to the front. The top face (dot) stays on top. The star moves from right to front.', '3D rotation around the vertical axis (side faces move, top stays).', ARRAY['p3','high_ability','spatial','rotation','challenge'], true, '{"type": "rotation_3d", "axis": "vertical", "marks": {"top": "dot", "right": "star"}, "rotation": "left 90", "star_after": "front"}'::jsonb, 'p3/BA_P3_0074.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0075', 'visual_spatial', 'Visual & Spatial', '4.5', 'position', 'Explore', 'easy', 'multiple_choice', 'In a 3-by-3 grid, the star is in the top-left square. The circle is directly below the star. The square is to the right of the circle. Where is the square?', '[{"id": "A", "text": "middle row, middle column"}, {"id": "B", "text": "top-left"}, {"id": "C", "text": "bottom-right"}, {"id": "D", "text": "top-right"}]'::jsonb, 'A', 'Top-left is row1 col1. Directly below = row2 col1 (circle). To the right of the circle = row2 col2 (square). So the square is in the middle row, middle column.', 'Tracking positions on a grid from relative clues.', ARRAY['p3','high_ability','spatial','position'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0076', 'visual_spatial', 'Visual & Spatial', '4.5', 'position', 'Think', 'medium', 'multiple_choice', 'A is to the left of B. C is above A. D is to the right of C. Which letter is in the top-right position?', '[{"id": "A", "text": "D"}, {"id": "B", "text": "A"}, {"id": "C", "text": "B"}, {"id": "D", "text": "C"}]'::jsonb, 'A', 'Place A left of B (same row). C above A (col1, row above). D right of C (col2, row above). The top-right position is D.', 'Combining left/right and above/below clues on a grid.', ARRAY['p3','high_ability','spatial','position'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0077', 'pattern_abstract', 'Pattern & Abstract', '5.1', 'count_sequence', 'Explore', 'easy', 'multiple_choice', 'Groups of dots: 1, then 2, then 4, then 8. How many dots come next?', '[{"id": "A", "text": "16"}, {"id": "B", "text": "10"}, {"id": "C", "text": "12"}, {"id": "D", "text": "9"}]'::jsonb, 'A', 'Each group has twice as many dots as the previous group: 1, 2, 4, 8, so 8 x 2 = 16.', 'Continuing a doubling count sequence.', ARRAY['p3','high_ability','pattern','sequence'], true, '{"type": "count_sequence", "counts": [1, 2, 4, 8], "next": 16}'::jsonb, 'p3/BA_P3_0077.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0181', 'numerical_reasoning', 'Numerical Thinking', '1.2', 'number_analogy', 'Explore', 'easy', 'multiple_choice', '2 is to 6 as 6 is to ___?', '[{"id": "A", "text": "12"}, {"id": "B", "text": "18"}, {"id": "C", "text": "10"}, {"id": "D", "text": "17"}]'::jsonb, 'B', 'Relation: x3. 2 -> 6, so 6 -> 18.', 'Inferring a numerical relation and applying it.', ARRAY['p3','high_ability','numerical','analogy'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0182', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 4, 8, 13, 19, 26, ___?', '[{"id": "A", "text": "35"}, {"id": "B", "text": "26"}, {"id": "C", "text": "34"}, {"id": "D", "text": "33"}]'::jsonb, 'C', 'The rule is: the gap between terms grows by 1 each step. So the next number is 34.', 'Finding the pattern in a number sequence.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0183', 'numerical_reasoning', 'Numerical Thinking', '1.2', 'number_analogy', 'Explore', 'easy', 'multiple_choice', '5 is to 7 as 7 is to ___?', '[{"id": "A", "text": "9"}, {"id": "B", "text": "11"}, {"id": "C", "text": "14"}, {"id": "D", "text": "8"}]'::jsonb, 'A', 'Relation: +2. 5 -> 7, so 7 -> 9.', 'Inferring a numerical relation and applying it.', ARRAY['p3','high_ability','numerical','analogy'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0184', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Master', 'expert', 'multiple_choice', 'Find the next number: 3, 6, 18, 21, 63, 66, ___?', '[{"id": "A", "text": "198"}, {"id": "B", "text": "201"}, {"id": "C", "text": "197"}, {"id": "D", "text": "66"}]'::jsonb, 'A', 'Rule: alternating rule: add 3, then multiply by 3, repeat. The 7th term = 198.', 'Two-rule alternating number sequence (expert).', ARRAY['p3','high_ability','numerical','pattern','master'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0185', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 5, 8, 12, 17, 23, 30, 38, ___?', '[{"id": "A", "text": "46"}, {"id": "B", "text": "47"}, {"id": "C", "text": "38"}, {"id": "D", "text": "48"}]'::jsonb, 'B', 'The rule is: the gap between terms grows by 1 each step. So the next number is 47.', 'Finding the pattern in a number sequence.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0188', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 4, 6, 6, 9, 8, 12, 10, ___?', '[{"id": "A", "text": "16"}, {"id": "B", "text": "15"}, {"id": "C", "text": "13"}, {"id": "D", "text": "12"}]'::jsonb, 'B', 'The rule is: two woven sequences: odd positions +2, even positions +3. So the next number is 15.', 'Finding the pattern in a number sequence.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0189', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Master', 'expert', 'multiple_choice', 'Find the next number: 3, 5, 10, 12, 24, 26, ___?', '[{"id": "A", "text": "51"}, {"id": "B", "text": "104"}, {"id": "C", "text": "54"}, {"id": "D", "text": "52"}]'::jsonb, 'D', 'Rule: alternating rule: add 2, then multiply by 2, repeat. The 7th term = 52.', 'Two-rule alternating number sequence (expert).', ARRAY['p3','high_ability','numerical','pattern','master'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0190', 'numerical_reasoning', 'Numerical Thinking', '1.2', 'number_analogy', 'Explore', 'easy', 'multiple_choice', '6 is to 12 as 2 is to ___?', '[{"id": "A", "text": "8"}, {"id": "B", "text": "10"}, {"id": "C", "text": "4"}, {"id": "D", "text": "3"}]'::jsonb, 'C', 'Relation: x2. 6 -> 12, so 2 -> 4.', 'Inferring a numerical relation and applying it.', ARRAY['p3','high_ability','numerical','analogy'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0191', 'numerical_reasoning', 'Numerical Thinking', '1.2', 'number_analogy', 'Think', 'medium', 'multiple_choice', '8 is to 22 as 5 is to ___?', '[{"id": "A", "text": "13"}, {"id": "B", "text": "27"}, {"id": "C", "text": "19"}, {"id": "D", "text": "10"}]'::jsonb, 'A', 'Relation: x3 then -2. 8 -> 22, so 5 -> 13.', 'Inferring a numerical relation and applying it.', ARRAY['p3','high_ability','numerical','analogy'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0192', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Master', 'expert', 'multiple_choice', 'Find the next number: 3, 7, 14, 18, 36, 40, ___?', '[{"id": "A", "text": "160"}, {"id": "B", "text": "80"}, {"id": "C", "text": "40"}, {"id": "D", "text": "84"}]'::jsonb, 'B', 'Rule: alternating rule: add 4, then multiply by 2, repeat. The 7th term = 80.', 'Two-rule alternating number sequence (expert).', ARRAY['p3','high_ability','numerical','pattern','master'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0193', 'numerical_reasoning', 'Numerical Thinking', '1.2', 'number_analogy', 'Challenge', 'hard', 'multiple_choice', '6 is to 36 as 7 is to ___?', '[{"id": "A", "text": "37"}, {"id": "B", "text": "14"}, {"id": "C", "text": "49"}, {"id": "D", "text": "79"}]'::jsonb, 'C', 'Relation: square the number. 6 -> 36, so 7 -> 49.', 'Inferring a numerical relation and applying it.', ARRAY['p3','high_ability','numerical','analogy'], false, NULL, NULL, false);
