INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0266', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 1, 3, 6, 10, 15, 21, ___?', '[{"id": "A", "text": "29"}, {"id": "B", "text": "21"}, {"id": "C", "text": "28"}, {"id": "D", "text": "27"}]'::jsonb, 'C', 'The rule is: the gap between terms grows by 1 each step. So the next number is 28.', 'Finding the pattern in a number sequence.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0267', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Explore', 'easy', 'multiple_choice', 'Find the next number: 2, 5, 7, 12, 19, 31, 50, ___?', '[{"id": "A", "text": "31"}, {"id": "B", "text": "81"}, {"id": "C", "text": "50"}, {"id": "D", "text": "83"}]'::jsonb, 'B', 'The rule is: each term is the sum of the two before it. So the next number is 81.', 'Finding the pattern in a number sequence.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0268', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Master', 'expert', 'multiple_choice', 'Find the next number: 4, 6, 18, 20, 60, 62, ___?', '[{"id": "A", "text": "185"}, {"id": "B", "text": "558"}, {"id": "C", "text": "62"}, {"id": "D", "text": "186"}]'::jsonb, 'D', 'Rule: alternating rule: add 2, then multiply by 3, repeat. The 7th term = 186.', 'Two-rule alternating number sequence (expert).', ARRAY['p3','high_ability','numerical','pattern','master'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0269', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 5, 14, 23, 32, 41, ___?', '[{"id": "A", "text": "59"}, {"id": "B", "text": "32"}, {"id": "C", "text": "51"}, {"id": "D", "text": "50"}]'::jsonb, 'D', 'The rule is: add 9 each step. So the next number is 50.', 'Finding the pattern in a number sequence.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0270', 'numerical_reasoning', 'Numerical Thinking', '1.1', 'number_sequence', 'Think', 'medium', 'multiple_choice', 'Find the next number: 2, 5, 3, 7, 4, 9, 5, ___?', '[{"id": "A", "text": "11"}, {"id": "B", "text": "12"}, {"id": "C", "text": "7"}, {"id": "D", "text": "9"}]'::jsonb, 'A', 'The rule is: two woven sequences: odd positions +1, even positions +2. So the next number is 11.', 'Finding the pattern in a number sequence.', ARRAY['p3','high_ability','numerical','pattern'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0277', 'logical_reasoning', 'Logical Thinking', '2.5', 'syllogism', 'Challenge', 'hard', 'multiple_choice', 'Some squares are red. All red things are small. Which MUST be true?', '[{"id": "A", "text": "All small things are squares"}, {"id": "B", "text": "All squares are small"}, {"id": "C", "text": "No squares are small"}, {"id": "D", "text": "Some squares are small"}]'::jsonb, 'D', 'The red squares are squares AND red; all red things are small, so those squares are small. Thus SOME squares are small.', 'Chaining a particular with a universal quantifier without over-generalising.', ARRAY['p3','high_ability','logical','syllogism'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0281', 'logical_reasoning', 'Logical Thinking', '2.5', 'syllogism', 'Challenge', 'hard', 'multiple_choice', 'Some squares are red. All red things are small. Which MUST be true?', '[{"id": "A", "text": "All small things are squares"}, {"id": "B", "text": "Some squares are small"}, {"id": "C", "text": "No squares are small"}, {"id": "D", "text": "All squares are small"}]'::jsonb, 'B', 'The red squares are squares AND red; all red things are small, so those squares are small. Thus SOME squares are small.', 'Chaining a particular with a universal quantifier without over-generalising.', ARRAY['p3','high_ability','logical','syllogism'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0282', 'logical_reasoning', 'Logical Thinking', '2.1', 'linear_order', 'Think', 'medium', 'multiple_choice', 'Four runners race. S beats T. T beats R. R beats P. Order them from fastest to slowest.', '[{"id": "A", "text": "S, T, R, P"}, {"id": "B", "text": "S, T, R, P1"}, {"id": "C", "text": "S, R, P, T"}, {"id": "D", "text": "T, P, R, S"}]'::jsonb, 'A', 'Chain the clues: S beats T, T beats R, R beats P, so S > T > R > P.', 'Merging a fully-determined ordering chain.', ARRAY['p3','high_ability','logical','ordering'], false, NULL, NULL, false);
