INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0526', 'verbal_reasoning', 'Verbal Reasoning', '3.3', 'codes_ciphers', 'Think', 'medium', 'multiple_choice', 'In a code, each letter means the letter 1 steps before it (so the code letter is ahead). The code word is NPPO. What real word does it stand for?', '[{"id": "A", "text": "MOON"}, {"id": "B", "text": "MOOX"}, {"id": "C", "text": "QOON"}, {"id": "D", "text": "BOON"}]'::jsonb, 'A', 'Each code letter is 1 ahead, so shift back 1: NPPO -> MOON.', 'Reversing a letter shift to decode.', ARRAY['p3','high_ability','verbal','cipher'], false, NULL, NULL, false);
