INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0592', 'verbal_reasoning', 'Verbal Reasoning', '3.3', 'codes_ciphers', 'Master', 'expert', 'multiple_choice', 'Secret code: move every letter forward 3 places (A->D), then reverse the whole word. What does RED become?', '[{"id": "A", "text": "UHG"}, {"id": "B", "text": "DER"}, {"id": "C", "text": "RED"}, {"id": "D", "text": "GHU"}]'::jsonb, 'D', 'Shift: RED -> UHG; reverse -> GHU.', 'Two-step cipher (shift then reverse) — rule discovery (expert).', ARRAY['p3','high_ability','verbal','code','master'], false, NULL, NULL, false);
