INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0671', 'verbal_reasoning', 'Verbal Reasoning', '3.3', 'codes_ciphers', 'Master', 'expert', 'multiple_choice', 'Secret code: move every letter forward 1 places (A->B), then reverse the whole word. What does SUN become?', '[{"id": "A", "text": "NUS"}, {"id": "B", "text": "OVT"}, {"id": "C", "text": "TVO"}, {"id": "D", "text": "SUN"}]'::jsonb, 'B', 'Shift: SUN -> TVO; reverse -> OVT.', 'Two-step cipher (shift then reverse) — rule discovery (expert).', ARRAY['p3','high_ability','verbal','code','master'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0672', 'visual_spatial', 'Visual & Spatial', '4.4', 'rotation_3d', 'Challenge', 'hard', 'multiple_choice', 'A cube has a cross on its TOP face and a star on its FRONT face. You rotate it 90 degrees to the left around the vertical axis. Where is the star now?', '[{"id": "A", "text": "left"}, {"id": "B", "text": "front"}, {"id": "C", "text": "top"}, {"id": "D", "text": "right"}]'::jsonb, 'A', 'Rotating around the vertical axis to the left turns the front face to the left; the top stays on top.', '3D rotation around the vertical axis.', ARRAY['p3','high_ability','spatial','rotation','challenge'], true, '{"type": "rotation_3d", "axis": "vertical", "marks": {"top": "cross", "front": "star"}, "rotation": "left 90", "star_after": "left"}'::jsonb, 'p3/BA_P3_0672.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0673', 'visual_spatial', 'Visual & Spatial', '4.5', 'position', 'Explore', 'easy', 'multiple_choice', 'On a 3-by-3 grid: the triangle is in the top-left square. The star is directly below the triangle. The square is to the right of the star. Where is the square?', '[{"id": "A", "text": "top-left"}, {"id": "B", "text": "middle row, middle column"}, {"id": "C", "text": "bottom-right"}, {"id": "D", "text": "bottom-left"}]'::jsonb, 'B', 'Top-left row1 col1; star below = row2 col1; square right of it = row2 col2 (middle row, middle column).', 'Tracking grid positions from relative clues.', ARRAY['p3','high_ability','spatial','position'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0675', 'visual_spatial', 'Visual & Spatial', '4.4', 'rotation_3d', 'Challenge', 'hard', 'multiple_choice', 'A cube has a dot on its TOP face and a star on its FRONT face. You rotate it 90 degrees to the right around the vertical axis. Where is the star now?', '[{"id": "A", "text": "right"}, {"id": "B", "text": "top"}, {"id": "C", "text": "left"}, {"id": "D", "text": "front"}]'::jsonb, 'A', 'Rotating around the vertical axis to the right turns the front face to the right; the top stays on top.', '3D rotation around the vertical axis.', ARRAY['p3','high_ability','spatial','rotation','challenge'], true, '{"type": "rotation_3d", "axis": "vertical", "marks": {"top": "dot", "front": "star"}, "rotation": "right 90", "star_after": "right"}'::jsonb, 'p3/BA_P3_0675.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0676', 'visual_spatial', 'Visual & Spatial', '4.3', 'cube_net', 'Think', 'medium', 'multiple_choice', 'A cube net: centre A, with F above, E below, D left, B right, and C below E. Folded with A as front, which square is the BACK face?', '[{"id": "A", "text": "F"}, {"id": "B", "text": "D"}, {"id": "C", "text": "E"}, {"id": "D", "text": "C"}]'::jsonb, 'D', 'Fold A as front: D=left, B=right, F=top, E=bottom, and C folds to the back. Back = C.', 'Folding a net to find the opposite face.', ARRAY['p3','high_ability','spatial','net'], true, '{"type": "cube_net", "layout": [["", "F", ""], ["D", "A", "B"], ["", "E", ""], ["", "C", ""]], "front": "A", "back": "C"}'::jsonb, 'p3/BA_P3_0676.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0679', 'visual_spatial', 'Visual & Spatial', '4.2', 'reflection', 'Think', 'medium', 'multiple_choice', 'The letter ''p'' is reflected in a vertical mirror (left-right flip). Which letter does the reflection look like?', '[{"id": "A", "text": "b"}, {"id": "B", "text": "d"}, {"id": "C", "text": "p"}, {"id": "D", "text": "q"}]'::jsonb, 'D', 'A vertical mirror flips ''p'' left-right so it looks like ''q''.', 'Mirror reflection across a vertical axis.', ARRAY['p3','high_ability','spatial','reflection'], true, '{"type": "reflection", "axis": "vertical", "source": "p", "result": "q"}'::jsonb, 'p3/BA_P3_0679.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0680', 'visual_spatial', 'Visual & Spatial', '4.5', 'position', 'Think', 'medium', 'multiple_choice', 'On a 3-by-3 grid: the circle is in the top-left square. The triangle is directly below the circle. The square is to the right of the triangle. Where is the square?', '[{"id": "A", "text": "bottom-left"}, {"id": "B", "text": "top-left"}, {"id": "C", "text": "middle row, middle column"}, {"id": "D", "text": "bottom-right"}]'::jsonb, 'C', 'Top-left row1 col1; triangle below = row2 col1; square right of it = row2 col2 (middle row, middle column).', 'Tracking grid positions from relative clues.', ARRAY['p3','high_ability','spatial','position'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0682', 'visual_spatial', 'Visual & Spatial', '4.3', 'cube_net', 'Think', 'medium', 'multiple_choice', 'A cube net: centre D, with F above, C below, E left, A right, and B below C. Folded with D as front, which square is the BACK face?', '[{"id": "A", "text": "E"}, {"id": "B", "text": "F"}, {"id": "C", "text": "B"}, {"id": "D", "text": "D"}]'::jsonb, 'C', 'Fold D as front: E=left, A=right, F=top, C=bottom, and B folds to the back. Back = B.', 'Folding a net to find the opposite face.', ARRAY['p3','high_ability','spatial','net'], true, '{"type": "cube_net", "layout": [["", "F", ""], ["E", "D", "A"], ["", "C", ""], ["", "B", ""]], "front": "D", "back": "B"}'::jsonb, 'p3/BA_P3_0682.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0683', 'visual_spatial', 'Visual & Spatial', '4.1', 'rotation', 'Think', 'medium', 'multiple_choice', 'An arrow points down. It is rotated 90 degrees clockwise 2 times. Which way does it point now?', '[{"id": "A", "text": "down"}, {"id": "B", "text": "right"}, {"id": "C", "text": "left"}, {"id": "D", "text": "up"}]'::jsonb, 'D', 'Each 90-degree clockwise turn moves the arrow one step: down -> ... -> up.', 'Mentally rotating a shape.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "rotation_sequence", "start": "down", "steps": 2}'::jsonb, 'p3/BA_P3_0683.svg', false);
