INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0708', 'visual_spatial', 'Visual & Spatial', '4.3', 'cube_net', 'Think', 'medium', 'multiple_choice', 'A cube net: centre C, with A above, B below, E left, F right, and D below B. Folded with C as front, which square is the BACK face?', '[{"id": "A", "text": "F"}, {"id": "B", "text": "B"}, {"id": "C", "text": "C"}, {"id": "D", "text": "D"}]'::jsonb, 'D', 'Fold C as front: E=left, F=right, A=top, B=bottom, and D folds to the back. Back = D.', 'Folding a net to find the opposite face.', ARRAY['p3','high_ability','spatial','net'], true, '{"type": "cube_net", "layout": [["", "A", ""], ["E", "C", "F"], ["", "B", ""], ["", "D", ""]], "front": "C", "back": "D"}'::jsonb, 'p3/BA_P3_0708.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0710', 'visual_spatial', 'Visual & Spatial', '4.4', 'rotation_3d', 'Challenge', 'hard', 'multiple_choice', 'A cube has a dot on its TOP face and a cross on its FRONT face. You rotate it 90 degrees to the left around the vertical axis. Where is the cross now?', '[{"id": "A", "text": "front"}, {"id": "B", "text": "right"}, {"id": "C", "text": "left"}, {"id": "D", "text": "top"}]'::jsonb, 'C', 'Rotating around the vertical axis to the left turns the front face to the left; the top stays on top.', '3D rotation around the vertical axis.', ARRAY['p3','high_ability','spatial','rotation','challenge'], true, '{"type": "rotation_3d", "axis": "vertical", "marks": {"top": "dot", "front": "cross"}, "rotation": "left 90", "star_after": "left"}'::jsonb, 'p3/BA_P3_0710.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0711', 'visual_spatial', 'Visual & Spatial', '4.1', 'rotation', 'Explore', 'easy', 'multiple_choice', 'An arrow points down. It is rotated 90 degrees clockwise once. Which way does it point now?', '[{"id": "A", "text": "right"}, {"id": "B", "text": "up"}, {"id": "C", "text": "down"}, {"id": "D", "text": "left"}]'::jsonb, 'D', 'Each 90-degree clockwise turn moves the arrow one step: down -> ... -> left.', 'Mentally rotating a shape.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "rotation_sequence", "start": "down", "steps": 1}'::jsonb, 'p3/BA_P3_0711.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0712', 'visual_spatial', 'Visual & Spatial', '4.6', 'transformation', 'Think', 'medium', 'multiple_choice', 'Each step the shape gains one side AND its colour alternates red, blue, red... triangle red(3) -> square blue(4) -> pentagon red(5) -> ?', '[{"id": "A", "text": "triangle blue(6)"}, {"id": "B", "text": "hexagon blue(7)"}, {"id": "C", "text": "circle"}, {"id": "D", "text": "hexagon blue(6)"}]'::jsonb, 'D', 'Two rules: sides go +1 and colour alternates red/blue. Next = hexagon blue(6).', 'Continuing a two-feature transformation.', ARRAY['p3','high_ability','spatial','transformation'], true, '{"type": "shape_transformation", "rule": "add one side AND alternate colour red/blue", "sequence": ["triangle red(3)", "square blue(4)", "pentagon red(5)", "hexagon blue(6)"]}'::jsonb, 'p3/BA_P3_0712.svg', false);
