INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0744', 'visual_spatial', 'Visual & Spatial', '4.5', 'position', 'Think', 'medium', 'multiple_choice', 'On a 3-by-3 grid: the square is in the top-left square. The triangle is directly below the square. The star is to the right of the triangle. Where is the star?', '[{"id": "A", "text": "bottom-left"}, {"id": "B", "text": "top-left"}, {"id": "C", "text": "top-right"}, {"id": "D", "text": "middle row, middle column"}]'::jsonb, 'D', 'Top-left row1 col1; triangle below = row2 col1; star right of it = row2 col2 (middle row, middle column).', 'Tracking grid positions from relative clues.', ARRAY['p3','high_ability','spatial','position'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0747', 'visual_spatial', 'Visual & Spatial', '4.3', 'cube_net', 'Think', 'medium', 'multiple_choice', 'A cube net: centre E, with F above, A below, C left, B right, and D below A. Folded with E as front, which square is the BACK face?', '[{"id": "A", "text": "D"}, {"id": "B", "text": "B"}, {"id": "C", "text": "E"}, {"id": "D", "text": "A"}]'::jsonb, 'A', 'Fold E as front: C=left, B=right, F=top, A=bottom, and D folds to the back. Back = D.', 'Folding a net to find the opposite face.', ARRAY['p3','high_ability','spatial','net'], true, '{"type": "cube_net", "layout": [["", "F", ""], ["C", "E", "B"], ["", "A", ""], ["", "D", ""]], "front": "E", "back": "D"}'::jsonb, 'p3/BA_P3_0747.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0750', 'visual_spatial', 'Visual & Spatial', '4.3', 'cube_net', 'Think', 'medium', 'multiple_choice', 'A cube net: centre A, with C above, B below, D left, E right, and F below B. Folded with A as front, which square is the BACK face?', '[{"id": "A", "text": "F"}, {"id": "B", "text": "B"}, {"id": "C", "text": "E"}, {"id": "D", "text": "D"}]'::jsonb, 'A', 'Fold A as front: D=left, E=right, C=top, B=bottom, and F folds to the back. Back = F.', 'Folding a net to find the opposite face.', ARRAY['p3','high_ability','spatial','net'], true, '{"type": "cube_net", "layout": [["", "C", ""], ["D", "A", "E"], ["", "B", ""], ["", "F", ""]], "front": "A", "back": "F"}'::jsonb, 'p3/BA_P3_0750.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0751', 'visual_spatial', 'Visual & Spatial', '4.6', 'transformation', 'Think', 'medium', 'multiple_choice', 'Each step the shape gains one side AND its colour alternates red, blue, red... triangle red(3) -> square blue(4) -> pentagon red(5) -> ?', '[{"id": "A", "text": "hexagon blue(7)"}, {"id": "B", "text": "circle"}, {"id": "C", "text": "hexagon blue(6)"}, {"id": "D", "text": "triangle blue(6)"}]'::jsonb, 'C', 'Two rules: sides go +1 and colour alternates red/blue. Next = hexagon blue(6).', 'Continuing a two-feature transformation.', ARRAY['p3','high_ability','spatial','transformation'], true, '{"type": "shape_transformation", "rule": "add one side AND alternate colour red/blue", "sequence": ["triangle red(3)", "square blue(4)", "pentagon red(5)", "hexagon blue(6)"]}'::jsonb, 'p3/BA_P3_0751.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0752', 'visual_spatial', 'Visual & Spatial', '4.1', 'rotation', 'Think', 'medium', 'multiple_choice', 'An arrow points left. It is rotated 90 degrees clockwise 3 times. Which way does it point now?', '[{"id": "A", "text": "down"}, {"id": "B", "text": "right"}, {"id": "C", "text": "up"}, {"id": "D", "text": "left"}]'::jsonb, 'A', 'Each 90-degree clockwise turn moves the arrow one step: left -> ... -> down.', 'Mentally rotating a shape.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "rotation_sequence", "start": "left", "steps": 3}'::jsonb, 'p3/BA_P3_0752.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0753', 'visual_spatial', 'Visual & Spatial', '4.4', 'rotation_3d', 'Challenge', 'hard', 'multiple_choice', 'A cube has a dot on its TOP face and a star on its FRONT face. You rotate it 90 degrees to the left around the vertical axis. Where is the star now?', '[{"id": "A", "text": "front"}, {"id": "B", "text": "top"}, {"id": "C", "text": "right"}, {"id": "D", "text": "left"}]'::jsonb, 'D', 'Rotating around the vertical axis to the left turns the front face to the left; the top stays on top.', '3D rotation around the vertical axis.', ARRAY['p3','high_ability','spatial','rotation','challenge'], true, '{"type": "rotation_3d", "axis": "vertical", "marks": {"top": "dot", "front": "star"}, "rotation": "left 90", "star_after": "left"}'::jsonb, 'p3/BA_P3_0753.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0756', 'visual_spatial', 'Visual & Spatial', '4.2', 'reflection', 'Think', 'medium', 'multiple_choice', 'The letter ''d'' is reflected in a vertical mirror (left-right flip). Which letter does the reflection look like?', '[{"id": "A", "text": "q"}, {"id": "B", "text": "d"}, {"id": "C", "text": "p"}, {"id": "D", "text": "b"}]'::jsonb, 'D', 'A vertical mirror flips ''d'' left-right so it looks like ''b''.', 'Mirror reflection across a vertical axis.', ARRAY['p3','high_ability','spatial','reflection'], true, '{"type": "reflection", "axis": "vertical", "source": "d", "result": "b"}'::jsonb, 'p3/BA_P3_0756.svg', false);
