INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0785', 'visual_spatial', 'Visual & Spatial', '4.4', 'rotation_3d', 'Challenge', 'hard', 'multiple_choice', 'A cube has a star on its TOP face and a cross on its FRONT face. You rotate it 90 degrees to the left around the vertical axis. Where is the cross now?', '[{"id": "A", "text": "right"}, {"id": "B", "text": "left"}, {"id": "C", "text": "front"}, {"id": "D", "text": "top"}]'::jsonb, 'B', 'Rotating around the vertical axis to the left turns the front face to the left; the top stays on top.', '3D rotation around the vertical axis.', ARRAY['p3','high_ability','spatial','rotation','challenge'], true, '{"type": "rotation_3d", "axis": "vertical", "marks": {"top": "star", "front": "cross"}, "rotation": "left 90", "star_after": "left"}'::jsonb, 'p3/BA_P3_0785.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0786', 'visual_spatial', 'Visual & Spatial', '4.1', 'rotation', 'Explore', 'easy', 'multiple_choice', 'An arrow points right. It is rotated 90 degrees clockwise once. Which way does it point now?', '[{"id": "A", "text": "right"}, {"id": "B", "text": "left"}, {"id": "C", "text": "down"}, {"id": "D", "text": "up"}]'::jsonb, 'C', 'Each 90-degree clockwise turn moves the arrow one step: right -> ... -> down.', 'Mentally rotating a shape.', ARRAY['p3','high_ability','spatial','rotation'], true, '{"type": "rotation_sequence", "start": "right", "steps": 1}'::jsonb, 'p3/BA_P3_0786.svg', false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_0787', 'visual_spatial', 'Visual & Spatial', '4.2', 'reflection', 'Think', 'medium', 'multiple_choice', 'The letter ''b'' is reflected in a vertical mirror (left-right flip). Which letter does the reflection look like?', '[{"id": "A", "text": "p"}, {"id": "B", "text": "q"}, {"id": "C", "text": "d"}, {"id": "D", "text": "b"}]'::jsonb, 'C', 'A vertical mirror flips ''b'' left-right so it looks like ''d''.', 'Mirror reflection across a vertical axis.', ARRAY['p3','high_ability','spatial','reflection'], true, '{"type": "reflection", "axis": "vertical", "source": "b", "result": "d"}'::jsonb, 'p3/BA_P3_0787.svg', false);
