INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_1111', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Think', 'medium', 'multiple_choice', 'A number is changed by: + 3; + 4. The final result is 13. What was the starting number? Check by going forward.', '[{"id": "A", "text": "6"}, {"id": "B", "text": "5"}, {"id": "C", "text": "8"}, {"id": "D", "text": "7"}]'::jsonb, 'A', 'Work backwards: before adding 4 there were 9; before adding 3 there were 6. Starting number = 6.', 'Working backwards through the steps and verifying.', ARRAY['p3','high_ability','heuristics','working_backwards'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_1112', 'problem_solving', 'Problem Solving', '6.2', 'guess_check', 'Think', 'medium', 'multiple_choice', 'Some coins are 2-dollar and some are 5-dollar. There are 9 coins in total and they make 30 dollars. How many 5-dollar coins are there?', '[{"id": "A", "text": "5"}, {"id": "B", "text": "0"}, {"id": "C", "text": "4"}, {"id": "D", "text": "6"}]'::jsonb, 'C', 'Try 4 five-dollar coins (= 20) and 5 two-dollar coins (= 10). Total 9 coins, 30 dollars. Fits, so 4 five-dollar coins.', 'Systematic guess-and-check across a few cases.', ARRAY['p3','high_ability','heuristics','guess_check'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_1115', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Think', 'medium', 'multiple_choice', 'A number is changed by: + 3; x 3. The final result is 36. What was the starting number? Check by going forward.', '[{"id": "A", "text": "18"}, {"id": "B", "text": "8"}, {"id": "C", "text": "9"}, {"id": "D", "text": "11"}]'::jsonb, 'C', 'Work backwards: before multiplying by 3 it was 12; before adding 3 there were 9. Starting number = 9.', 'Working backwards through the steps and verifying.', ARRAY['p3','high_ability','heuristics','working_backwards'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_1116', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Challenge', 'hard', 'multiple_choice', 'A number is changed by: + 2; + 3; + 3. The final result is 13. What was the starting number? Check by going forward.', '[{"id": "A", "text": "7"}, {"id": "B", "text": "5"}, {"id": "C", "text": "4"}, {"id": "D", "text": "10"}]'::jsonb, 'B', 'Work backwards: before adding 3 there were 10; before adding 3 there were 7; before adding 2 there were 5. Starting number = 5.', 'Working backwards through the steps and verifying.', ARRAY['p3','high_ability','heuristics','working_backwards'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_1119', 'problem_solving', 'Problem Solving', '6.2', 'guess_check', 'Think', 'medium', 'multiple_choice', 'Some coins are 2-dollar and some are 5-dollar. There are 6 coins in total and they make 21 dollars. How many 5-dollar coins are there?', '[{"id": "A", "text": "3"}, {"id": "B", "text": "0"}, {"id": "C", "text": "5"}, {"id": "D", "text": "4"}]'::jsonb, 'A', 'Try 3 five-dollar coins (= 15) and 3 two-dollar coins (= 6). Total 6 coins, 21 dollars. Fits, so 3 five-dollar coins.', 'Systematic guess-and-check across a few cases.', ARRAY['p3','high_ability','heuristics','guess_check'], false, NULL, NULL, false);
