INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_1239', 'problem_solving', 'Problem Solving', '6.1', 'working_backwards', 'Challenge', 'hard', 'multiple_choice', 'A number is changed by: + 3; + 5; + 5. The final result is 17. What was the starting number? Check by going forward.', '[{"id": "A", "text": "8"}, {"id": "B", "text": "6"}, {"id": "C", "text": "4"}, {"id": "D", "text": "5"}]'::jsonb, 'C', 'Work backwards: before adding 5 there were 12; before adding 5 there were 7; before adding 3 there were 4. Starting number = 4.', 'Working backwards through the steps and verifying.', ARRAY['p3','high_ability','heuristics','working_backwards'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G001', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A triangle and a square together weigh 8 kg. A square and a circle together weigh 12 kg. A triangle and a circle together weigh 10 kg. Which shape is the heaviest?', '[{"id": "A", "text": "cannot tell"}, {"id": "B", "text": "square"}, {"id": "C", "text": "triangle"}, {"id": "D", "text": "circle"}]'::jsonb, 'D', 'Adding all three pairs gives 2 × (triangle + square + circle) = 8 + 12 + 10 = 30 kg. So all three shapes together weigh 15 kg. Then: triangle = 15 − 12 = 3 kg, square = 15 − 10 = 5 kg, and circle = 15 − 8 = 7 kg. Comparing the weights (3 kg, 5 kg, 7 kg), the heaviest is the circle (7 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G002', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A star and a diamond together weigh 6 g. A diamond and a oval together weigh 13 g. A star and a oval together weigh 11 g. Which shape is the lightest?', '[{"id": "A", "text": "oval"}, {"id": "B", "text": "star"}, {"id": "C", "text": "diamond"}, {"id": "D", "text": "cannot tell"}]'::jsonb, 'B', 'The sum of all three pairs is 6 + 13 + 11 = 30 g, which is double the total weight. Total weight of all three shapes = 15 g. Individual weights: star = 15 − 13 = 2 g, diamond = 15 − 11 = 4 g, oval = 15 − 6 = 9 g. Comparing the weights (2 g, 4 g, 9 g), the lightest is the star (2 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G003', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A heart and a crescent weigh 9 units together. A crescent and a cross weigh 14 units together. A heart and a cross weigh 11 units together. What is the weight of one crescent?', '[{"id": "A", "text": "6 units"}, {"id": "B", "text": "8 units"}, {"id": "C", "text": "11 units"}, {"id": "D", "text": "3 units"}]'::jsonb, 'A', 'Summing the three pair weights gives 2 × (heart + crescent + cross) = 9 + 14 + 11 = 34 units. Thus, one of each shape totals 17 units. Since heart + cross = 11 units, the crescent weighs 17 − 11 = 6 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G004', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'On a balance scale, a pentagon and a hexagon balance 9 kg. A hexagon and a octagon balance 12 kg. A pentagon and a octagon balance 11 kg. What is the total weight of one pentagon, one hexagon, and one octagon together?', '[{"id": "A", "text": "16 kg"}, {"id": "B", "text": "14 kg"}, {"id": "C", "text": "18 kg"}, {"id": "D", "text": "32 kg"}]'::jsonb, 'A', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (pentagon + hexagon + octagon) = 9 + 12 + 11 = 32 kg. Dividing by 2 gives the total weight of all three shapes: 32 ÷ 2 = 16 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G005', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A cube and a cylinder together weigh 7 kg. A cylinder and a cone together weigh 13 kg. A cube and a cone together weigh 10 kg. Which shape is the heaviest?', '[{"id": "A", "text": "cone"}, {"id": "B", "text": "cylinder"}, {"id": "C", "text": "cannot tell"}, {"id": "D", "text": "cube"}]'::jsonb, 'A', 'Adding all three pairs gives 2 × (cube + cylinder + cone) = 7 + 13 + 10 = 30 kg. So all three shapes together weigh 15 kg. Then: cube = 15 − 13 = 2 kg, cylinder = 15 − 10 = 5 kg, and cone = 15 − 7 = 8 kg. Comparing the weights (2 kg, 5 kg, 8 kg), the heaviest is the cone (8 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G006', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A red block and a blue block together weigh 7 g. A blue block and a yellow block together weigh 13 g. A red block and a yellow block together weigh 12 g. Which shape is the lightest?', '[{"id": "A", "text": "yellow block"}, {"id": "B", "text": "cannot tell"}, {"id": "C", "text": "blue block"}, {"id": "D", "text": "red block"}]'::jsonb, 'D', 'The sum of all three pairs is 7 + 13 + 12 = 32 g, which is double the total weight. Total weight of all three shapes = 16 g. Individual weights: red block = 16 − 13 = 3 g, blue block = 16 − 12 = 4 g, yellow block = 16 − 7 = 9 g. Comparing the weights (3 g, 4 g, 9 g), the lightest is the red block (3 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G007', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A gold coin and a silver coin weigh 11 units together. A silver coin and a bronze coin weigh 14 units together. A gold coin and a bronze coin weigh 13 units together. What is the weight of one silver coin?', '[{"id": "A", "text": "13 units"}, {"id": "B", "text": "6 units"}, {"id": "C", "text": "8 units"}, {"id": "D", "text": "5 units"}]'::jsonb, 'B', 'Summing the three pair weights gives 2 × (gold coin + silver coin + bronze coin) = 11 + 14 + 13 = 38 units. Thus, one of each shape totals 19 units. Since gold coin + bronze coin = 13 units, the silver coin weighs 19 − 13 = 6 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G008', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'On a balance scale, a apple and a orange balance 10 kg. A orange and a pear balance 17 kg. A apple and a pear balance 13 kg. What is the total weight of one apple, one orange, and one pear together?', '[{"id": "A", "text": "20 kg"}, {"id": "B", "text": "18 kg"}, {"id": "C", "text": "22 kg"}, {"id": "D", "text": "40 kg"}]'::jsonb, 'A', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (apple + orange + pear) = 10 + 17 + 13 = 40 kg. Dividing by 2 gives the total weight of all three shapes: 40 ÷ 2 = 20 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G009', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A ruby and a sapphire together weigh 10 kg. A sapphire and a emerald together weigh 15 kg. A ruby and a emerald together weigh 13 kg. Which shape is the heaviest?', '[{"id": "A", "text": "sapphire"}, {"id": "B", "text": "emerald"}, {"id": "C", "text": "cannot tell"}, {"id": "D", "text": "ruby"}]'::jsonb, 'B', 'Adding all three pairs gives 2 × (ruby + sapphire + emerald) = 10 + 15 + 13 = 38 kg. So all three shapes together weigh 19 kg. Then: ruby = 19 − 15 = 4 kg, sapphire = 19 − 13 = 6 kg, and emerald = 19 − 10 = 9 kg. Comparing the weights (4 kg, 6 kg, 9 kg), the heaviest is the emerald (9 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G010', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A pyramid and a sphere together weigh 9 g. A sphere and a prism together weigh 16 g. A pyramid and a prism together weigh 11 g. Which shape is the lightest?', '[{"id": "A", "text": "cannot tell"}, {"id": "B", "text": "pyramid"}, {"id": "C", "text": "sphere"}, {"id": "D", "text": "prism"}]'::jsonb, 'B', 'The sum of all three pairs is 9 + 16 + 11 = 36 g, which is double the total weight. Total weight of all three shapes = 18 g. Individual weights: pyramid = 18 − 16 = 2 g, sphere = 18 − 11 = 7 g, prism = 18 − 9 = 9 g. Comparing the weights (2 g, 7 g, 9 g), the lightest is the pyramid (2 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G011', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A triangle and a square weigh 11 units together. A square and a circle weigh 15 units together. A triangle and a circle weigh 12 units together. What is the weight of one square?', '[{"id": "A", "text": "12 units"}, {"id": "B", "text": "8 units"}, {"id": "C", "text": "7 units"}, {"id": "D", "text": "4 units"}]'::jsonb, 'C', 'Summing the three pair weights gives 2 × (triangle + square + circle) = 11 + 15 + 12 = 38 units. Thus, one of each shape totals 19 units. Since triangle + circle = 12 units, the square weighs 19 − 12 = 7 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G012', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'On a balance scale, a star and a diamond balance 11 kg. A diamond and a oval balance 17 kg. A star and a oval balance 12 kg. What is the total weight of one star, one diamond, and one oval together?', '[{"id": "A", "text": "22 kg"}, {"id": "B", "text": "20 kg"}, {"id": "C", "text": "18 kg"}, {"id": "D", "text": "40 kg"}]'::jsonb, 'B', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (star + diamond + oval) = 11 + 17 + 12 = 40 kg. Dividing by 2 gives the total weight of all three shapes: 40 ÷ 2 = 20 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G013', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A heart and a crescent together weigh 12 kg. A crescent and a cross together weigh 18 kg. A heart and a cross together weigh 16 kg. Which shape is the heaviest?', '[{"id": "A", "text": "heart"}, {"id": "B", "text": "crescent"}, {"id": "C", "text": "cannot tell"}, {"id": "D", "text": "cross"}]'::jsonb, 'D', 'Adding all three pairs gives 2 × (heart + crescent + cross) = 12 + 18 + 16 = 46 kg. So all three shapes together weigh 23 kg. Then: heart = 23 − 18 = 5 kg, crescent = 23 − 16 = 7 kg, and cross = 23 − 12 = 11 kg. Comparing the weights (5 kg, 7 kg, 11 kg), the heaviest is the cross (11 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G014', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A pentagon and a hexagon together weigh 8 g. A hexagon and a octagon together weigh 17 g. A pentagon and a octagon together weigh 13 g. Which shape is the lightest?', '[{"id": "A", "text": "hexagon"}, {"id": "B", "text": "pentagon"}, {"id": "C", "text": "octagon"}, {"id": "D", "text": "cannot tell"}]'::jsonb, 'B', 'The sum of all three pairs is 8 + 17 + 13 = 38 g, which is double the total weight. Total weight of all three shapes = 19 g. Individual weights: pentagon = 19 − 17 = 2 g, hexagon = 19 − 13 = 6 g, octagon = 19 − 8 = 11 g. Comparing the weights (2 g, 6 g, 11 g), the lightest is the pentagon (2 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G015', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A cube and a cylinder weigh 12 units together. A cylinder and a cone weigh 18 units together. A cube and a cone weigh 14 units together. What is the weight of one cylinder?', '[{"id": "A", "text": "4 units"}, {"id": "B", "text": "14 units"}, {"id": "C", "text": "10 units"}, {"id": "D", "text": "8 units"}]'::jsonb, 'D', 'Summing the three pair weights gives 2 × (cube + cylinder + cone) = 12 + 18 + 14 = 44 units. Thus, one of each shape totals 22 units. Since cube + cone = 14 units, the cylinder weighs 22 − 14 = 8 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G016', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'On a balance scale, a red block and a blue block balance 8 kg. A blue block and a yellow block balance 17 kg. A red block and a yellow block balance 15 kg. What is the total weight of one red block, one blue block, and one yellow block together?', '[{"id": "A", "text": "20 kg"}, {"id": "B", "text": "22 kg"}, {"id": "C", "text": "40 kg"}, {"id": "D", "text": "18 kg"}]'::jsonb, 'A', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (red block + blue block + yellow block) = 8 + 17 + 15 = 40 kg. Dividing by 2 gives the total weight of all three shapes: 40 ÷ 2 = 20 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G017', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A gold coin and a silver coin together weigh 13 kg. A silver coin and a bronze coin together weigh 16 kg. A gold coin and a bronze coin together weigh 15 kg. Which shape is the heaviest?', '[{"id": "A", "text": "cannot tell"}, {"id": "B", "text": "gold coin"}, {"id": "C", "text": "bronze coin"}, {"id": "D", "text": "silver coin"}]'::jsonb, 'C', 'Adding all three pairs gives 2 × (gold coin + silver coin + bronze coin) = 13 + 16 + 15 = 44 kg. So all three shapes together weigh 22 kg. Then: gold coin = 22 − 16 = 6 kg, silver coin = 22 − 15 = 7 kg, and bronze coin = 22 − 13 = 9 kg. Comparing the weights (6 kg, 7 kg, 9 kg), the heaviest is the bronze coin (9 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G018', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A apple and a orange together weigh 13 g. A orange and a pear together weigh 20 g. A apple and a pear together weigh 15 g. Which shape is the lightest?', '[{"id": "A", "text": "cannot tell"}, {"id": "B", "text": "orange"}, {"id": "C", "text": "apple"}, {"id": "D", "text": "pear"}]'::jsonb, 'C', 'The sum of all three pairs is 13 + 20 + 15 = 48 g, which is double the total weight. Total weight of all three shapes = 24 g. Individual weights: apple = 24 − 20 = 4 g, orange = 24 − 15 = 9 g, pear = 24 − 13 = 11 g. Comparing the weights (4 g, 9 g, 11 g), the lightest is the apple (4 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G019', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'A ruby and a sapphire weigh 13 units together. A sapphire and a emerald weigh 20 units together. A ruby and a emerald weigh 17 units together. What is the weight of one sapphire?', '[{"id": "A", "text": "17 units"}, {"id": "B", "text": "8 units"}, {"id": "C", "text": "5 units"}, {"id": "D", "text": "12 units"}]'::jsonb, 'B', 'Summing the three pair weights gives 2 × (ruby + sapphire + emerald) = 13 + 20 + 17 = 50 units. Thus, one of each shape totals 25 units. Since ruby + emerald = 17 units, the sapphire weighs 25 − 17 = 8 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G020', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Think', 'medium', 'multiple_choice', 'On a balance scale, a pyramid and a sphere balance 12 kg. A sphere and a prism balance 19 kg. A pyramid and a prism balance 13 kg. What is the total weight of one pyramid, one sphere, and one prism together?', '[{"id": "A", "text": "20 kg"}, {"id": "B", "text": "44 kg"}, {"id": "C", "text": "22 kg"}, {"id": "D", "text": "24 kg"}]'::jsonb, 'C', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (pyramid + sphere + prism) = 12 + 19 + 13 = 44 kg. Dividing by 2 gives the total weight of all three shapes: 44 ÷ 2 = 22 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G021', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Explore', 'easy', 'multiple_choice', 'A triangle and a square together weigh 10 kg. A square and a circle together weigh 21 kg. A triangle and a circle together weigh 15 kg. Which shape is the heaviest?', '[{"id": "A", "text": "square"}, {"id": "B", "text": "cannot tell"}, {"id": "C", "text": "circle"}, {"id": "D", "text": "triangle"}]'::jsonb, 'C', 'Adding all three pairs gives 2 × (triangle + square + circle) = 10 + 21 + 15 = 46 kg. So all three shapes together weigh 23 kg. Then: triangle = 23 − 21 = 2 kg, square = 23 − 15 = 8 kg, and circle = 23 − 10 = 13 kg. Comparing the weights (2 kg, 8 kg, 13 kg), the heaviest is the circle (13 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
