INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G029', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Explore', 'easy', 'multiple_choice', 'A ruby and a sapphire together weigh 15 kg. A sapphire and a emerald together weigh 19 kg. A ruby and a emerald together weigh 16 kg. Which shape is the heaviest?', '[{"id": "A", "text": "ruby"}, {"id": "B", "text": "cannot tell"}, {"id": "C", "text": "emerald"}, {"id": "D", "text": "sapphire"}]'::jsonb, 'C', 'Adding all three pairs gives 2 × (ruby + sapphire + emerald) = 15 + 19 + 16 = 50 kg. So all three shapes together weigh 25 kg. Then: ruby = 25 − 19 = 6 kg, sapphire = 25 − 16 = 9 kg, and emerald = 25 − 15 = 10 kg. Comparing the weights (6 kg, 9 kg, 10 kg), the heaviest is the emerald (10 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G030', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Explore', 'easy', 'multiple_choice', 'A pyramid and a sphere together weigh 9 g. A sphere and a prism together weigh 19 g. A pyramid and a prism together weigh 16 g. Which shape is the lightest?', '[{"id": "A", "text": "pyramid"}, {"id": "B", "text": "cannot tell"}, {"id": "C", "text": "sphere"}, {"id": "D", "text": "prism"}]'::jsonb, 'A', 'The sum of all three pairs is 9 + 19 + 16 = 44 g, which is double the total weight. Total weight of all three shapes = 22 g. Individual weights: pyramid = 22 − 19 = 3 g, sphere = 22 − 16 = 6 g, prism = 22 − 9 = 13 g. Comparing the weights (3 g, 6 g, 13 g), the lightest is the pyramid (3 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G031', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'A triangle and a square weigh 13 units together. A square and a circle weigh 19 units together. A triangle and a circle weigh 16 units together. What is the weight of one square?', '[{"id": "A", "text": "5 units"}, {"id": "B", "text": "11 units"}, {"id": "C", "text": "16 units"}, {"id": "D", "text": "8 units"}]'::jsonb, 'D', 'Summing the three pair weights gives 2 × (triangle + square + circle) = 13 + 19 + 16 = 48 units. Thus, one of each shape totals 24 units. Since triangle + circle = 16 units, the square weighs 24 − 16 = 8 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G032', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'On a balance scale, a star and a diamond balance 11 kg. A diamond and a oval balance 19 kg. A star and a oval balance 16 kg. What is the total weight of one star, one diamond, and one oval together?', '[{"id": "A", "text": "25 kg"}, {"id": "B", "text": "21 kg"}, {"id": "C", "text": "46 kg"}, {"id": "D", "text": "23 kg"}]'::jsonb, 'D', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (star + diamond + oval) = 11 + 19 + 16 = 46 kg. Dividing by 2 gives the total weight of all three shapes: 46 ÷ 2 = 23 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G033', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'A heart and a crescent together weigh 13 kg. A crescent and a cross together weigh 18 kg. A heart and a cross together weigh 17 kg. Which shape is the heaviest?', '[{"id": "A", "text": "cross"}, {"id": "B", "text": "heart"}, {"id": "C", "text": "cannot tell"}, {"id": "D", "text": "crescent"}]'::jsonb, 'A', 'Adding all three pairs gives 2 × (heart + crescent + cross) = 13 + 18 + 17 = 48 kg. So all three shapes together weigh 24 kg. Then: heart = 24 − 18 = 6 kg, crescent = 24 − 17 = 7 kg, and cross = 24 − 13 = 11 kg. Comparing the weights (6 kg, 7 kg, 11 kg), the heaviest is the cross (11 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G034', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'A pentagon and a hexagon together weigh 12 g. A hexagon and a octagon together weigh 23 g. A pentagon and a octagon together weigh 15 g. Which shape is the lightest?', '[{"id": "A", "text": "pentagon"}, {"id": "B", "text": "octagon"}, {"id": "C", "text": "cannot tell"}, {"id": "D", "text": "hexagon"}]'::jsonb, 'A', 'The sum of all three pairs is 12 + 23 + 15 = 50 g, which is double the total weight. Total weight of all three shapes = 25 g. Individual weights: pentagon = 25 − 23 = 2 g, hexagon = 25 − 15 = 10 g, octagon = 25 − 12 = 13 g. Comparing the weights (2 g, 10 g, 13 g), the lightest is the pentagon (2 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G035', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'A cube and a cylinder weigh 15 units together. A cylinder and a cone weigh 18 units together. A cube and a cone weigh 17 units together. What is the weight of one cylinder?', '[{"id": "A", "text": "10 units"}, {"id": "B", "text": "7 units"}, {"id": "C", "text": "8 units"}, {"id": "D", "text": "17 units"}]'::jsonb, 'C', 'Summing the three pair weights gives 2 × (cube + cylinder + cone) = 15 + 18 + 17 = 50 units. Thus, one of each shape totals 25 units. Since cube + cone = 17 units, the cylinder weighs 25 − 17 = 8 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G036', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'On a balance scale, a red block and a blue block balance 11 kg. A blue block and a yellow block balance 19 kg. A red block and a yellow block balance 14 kg. What is the total weight of one red block, one blue block, and one yellow block together?', '[{"id": "A", "text": "20 kg"}, {"id": "B", "text": "22 kg"}, {"id": "C", "text": "44 kg"}, {"id": "D", "text": "24 kg"}]'::jsonb, 'B', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (red block + blue block + yellow block) = 11 + 19 + 14 = 44 kg. Dividing by 2 gives the total weight of all three shapes: 44 ÷ 2 = 22 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G037', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'A gold coin and a silver coin together weigh 14 kg. A silver coin and a bronze coin together weigh 21 kg. A gold coin and a bronze coin together weigh 17 kg. Which shape is the heaviest?', '[{"id": "A", "text": "cannot tell"}, {"id": "B", "text": "silver coin"}, {"id": "C", "text": "gold coin"}, {"id": "D", "text": "bronze coin"}]'::jsonb, 'D', 'Adding all three pairs gives 2 × (gold coin + silver coin + bronze coin) = 14 + 21 + 17 = 52 kg. So all three shapes together weigh 26 kg. Then: gold coin = 26 − 21 = 5 kg, silver coin = 26 − 17 = 9 kg, and bronze coin = 26 − 14 = 12 kg. Comparing the weights (5 kg, 9 kg, 12 kg), the heaviest is the bronze coin (12 kg).', 'Solving a 3-variable balance system by summing pair equations and subtracting.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G038', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'A apple and a orange together weigh 12 g. A orange and a pear together weigh 21 g. A apple and a pear together weigh 17 g. Which shape is the lightest?', '[{"id": "A", "text": "pear"}, {"id": "B", "text": "orange"}, {"id": "C", "text": "cannot tell"}, {"id": "D", "text": "apple"}]'::jsonb, 'D', 'The sum of all three pairs is 12 + 21 + 17 = 50 g, which is double the total weight. Total weight of all three shapes = 25 g. Individual weights: apple = 25 − 21 = 4 g, orange = 25 − 17 = 8 g, pear = 25 − 12 = 13 g. Comparing the weights (4 g, 8 g, 13 g), the lightest is the apple (4 g).', 'Solving a 3-variable balance system to identify the minimum weight.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G039', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'A ruby and a sapphire weigh 14 units together. A sapphire and a emerald weigh 21 units together. A ruby and a emerald weigh 19 units together. What is the weight of one sapphire?', '[{"id": "A", "text": "8 units"}, {"id": "B", "text": "6 units"}, {"id": "C", "text": "19 units"}, {"id": "D", "text": "13 units"}]'::jsonb, 'A', 'Summing the three pair weights gives 2 × (ruby + sapphire + emerald) = 14 + 21 + 19 = 54 units. Thus, one of each shape totals 27 units. Since ruby + emerald = 19 units, the sapphire weighs 27 − 19 = 8 units.', 'Finding an individual shape weight from three pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G040', 'numerical_reasoning', 'Numerical Thinking', '1.3', 'weight_system', 'Challenge', 'hard', 'multiple_choice', 'On a balance scale, a pyramid and a sphere balance 16 kg. A sphere and a prism balance 20 kg. A pyramid and a prism balance 18 kg. What is the total weight of one pyramid, one sphere, and one prism together?', '[{"id": "A", "text": "29 kg"}, {"id": "B", "text": "54 kg"}, {"id": "C", "text": "25 kg"}, {"id": "D", "text": "27 kg"}]'::jsonb, 'D', 'Each shape appears exactly twice across the three pair measurements. Adding the three pairs gives 2 × (pyramid + sphere + prism) = 16 + 20 + 18 = 54 kg. Dividing by 2 gives the total weight of all three shapes: 54 ÷ 2 = 27 kg.', 'Deducing the sum of three items by taking half of their pairwise sums.', ARRAY['p3','high_ability','numerical','deduction','balance_system'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G041', 'numerical_reasoning', 'Numerical Thinking', '1.4', 'chain_comparison', 'Think', 'medium', 'multiple_choice', 'Ali has 4 more cards than Ben. Ben has 6 fewer cards than Cai. Cai has 15 cards. Who has the most cards?', '[{"id": "A", "text": "Ali"}, {"id": "B", "text": "cannot tell"}, {"id": "C", "text": "Ben"}, {"id": "D", "text": "Cai"}]'::jsonb, 'D', 'Start with Cai: Cai = 15. From the clues: Ben = 9 cards, and Ali = 13 cards. Comparing the amounts (Ali: 13, Ben: 9, Cai: 15), Cai has the most (15 cards).', 'Chaining relative comparison clues step-by-step to find an exact count or extreme.', ARRAY['p3','high_ability','numerical','comparison','ordering'], false, NULL, NULL, false);
