INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G056', 'numerical_reasoning', 'Numerical Thinking', '1.4', 'chain_comparison', 'Challenge', 'hard', 'multiple_choice', 'Una has 8 fewer balloons than Vince. Vince has 10 fewer balloons than Wren. Wren has 32 balloons. Who has the most balloons?', '[{"id": "A", "text": "Vince"}, {"id": "B", "text": "Una"}, {"id": "C", "text": "Wren"}, {"id": "D", "text": "cannot tell"}]'::jsonb, 'C', 'Start with Wren: Wren = 32. From the clues: Vince = 22 balloons, and Una = 14 balloons. Comparing the amounts (Una: 14, Vince: 22, Wren: 32), Wren has the most (32 balloons).', 'Chaining relative comparison clues step-by-step to find an exact count or extreme.', ARRAY['p3','high_ability','numerical','comparison','ordering'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G057', 'numerical_reasoning', 'Numerical Thinking', '1.4', 'chain_comparison', 'Challenge', 'hard', 'multiple_choice', 'Alex has 7 more magnets than Beth. Beth has 5 fewer magnets than Cole. Cole has 21 magnets. Who has the fewest magnets?', '[{"id": "A", "text": "Cole"}, {"id": "B", "text": "Beth"}, {"id": "C", "text": "cannot tell"}, {"id": "D", "text": "Alex"}]'::jsonb, 'B', 'Find each person''s amount step by step: Cole = 21. Beth = 16. Alex = 23. Comparing 23, 16, and 21, Beth has the fewest (16 magnets).', 'Chaining relative comparison clues step-by-step to find an exact count or extreme.', ARRAY['p3','high_ability','numerical','comparison','ordering'], false, NULL, NULL, false);
