INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G061', 'logical_reasoning', 'Logical Thinking', '2.2', 'constraint_placement', 'Think', 'medium', 'multiple_choice', 'Ali, Ben, Cai, and Dan sit in a cinema row with seats 1 to 4 from left to right. Dan sits in position 1 at the left end. Ben is not at either end. Cai sits immediately to the right of Ben. Who sits in seat 2?', '[{"id": "A", "text": "Dan"}, {"id": "B", "text": "Ali"}, {"id": "C", "text": "Cai"}, {"id": "D", "text": "Ben"}]'::jsonb, 'D', 'Position 1 is occupied by Dan. Since Ben is not at either end and Cai sits immediately to the right of Ben, Ben and Cai must occupy positions 2 and 3 respectively (with Ben in 2 and Cai in 3). This leaves position 4 for Ali. Therefore, Ben sits in position 2.', 'Applying multiple spatial and logical constraints to deduce unstated positions.', ARRAY['p3','high_ability','logical','deduction','constraint','seating'], false, NULL, NULL, false);
