INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G080', 'logical_reasoning', 'Logical Thinking', '2.2', 'constraint_placement', 'Think', 'medium', 'multiple_choice', 'Leo, Mila, Nico, and Olive sit in four laboratory seats numbered 1 to 4. Leo sits in position 4 at the far right. Mila sits immediately to the left of Leo. Olive sits somewhere to the left of Nico. Who sits in seat 1?', '[{"id": "A", "text": "Nico"}, {"id": "B", "text": "Mila"}, {"id": "C", "text": "Leo"}, {"id": "D", "text": "Olive"}]'::jsonb, 'D', 'Position 4 is Leo. Mila sits immediately to the left of Leo, placing Mila in position 3. Positions 1 and 2 remain for Olive and Nico. Since Olive is to the left of Nico, Olive is in position 1 and Nico in position 2. Full order: 1:Olive, 2:Nico, 3:Mila, 4:Leo. Thus, Olive is in position 1.', 'Applying multiple spatial and logical constraints to deduce unstated positions.', ARRAY['p3','high_ability','logical','deduction','constraint','seating'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G081', 'logical_reasoning', 'Logical Thinking', '2.2', 'constraint_placement', 'Explore', 'easy', 'multiple_choice', 'Peter, Quinn, Rose, and Sean competed in a 100m sprint race. There were no ties. Quinn finished in 2nd place. Peter finished immediately after Rose. Sean did not finish in 1st place. Who finished in 1st place?', '[{"id": "A", "text": "Quinn"}, {"id": "B", "text": "Peter"}, {"id": "C", "text": "Rose"}, {"id": "D", "text": "Sean"}]'::jsonb, 'C', 'Quinn is 2nd. Peter finished immediately after Rose, so Rose and Peter must occupy adjacent places. With 2nd place taken by Quinn, the pair Rose and Peter must be 3rd and 4th or 1st and 3rd? Since Peter is immediately after Rose, Rose must be 1st and Peter 3rd (separated by 2nd) or Rose is 3rd and Peter is 4th. If Rose were 3rd and Peter 4th, 1st place would be Sean, but the clue states Sean did not finish 1st! Thus, Rose is 1st, Quinn is 2nd, Peter is 3rd, and Sean is 4th. Therefore, Rose finished in 1st place.', 'Applying multiple spatial and logical constraints to deduce unstated positions.', ARRAY['p3','high_ability','logical','deduction','constraint','seating'], false, NULL, NULL, false);
