INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G099', 'logical_reasoning', 'Logical Thinking', '2.2', 'constraint_placement', 'Challenge', 'hard', 'multiple_choice', 'Joy, Keith, Luna, and Milo are queued up at the bookshop register. Joy is 1st in line. Luna is standing behind Keith. Milo is standing immediately between Joy and Keith. Who is 2nd in line?', '[{"id": "A", "text": "Joy"}, {"id": "B", "text": "Luna"}, {"id": "C", "text": "Milo"}, {"id": "D", "text": "Keith"}]'::jsonb, 'C', 'Joy is 1st. Milo is immediately between Joy and Keith, placing Milo 2nd and Keith 3rd. Since Luna is behind Keith, Luna must be 4th in line. Queue order: 1st:Joy, 2nd:Milo, 3rd:Keith, 4th:Luna. So Milo is 2nd in line.', 'Applying multiple spatial and logical constraints to deduce unstated positions.', ARRAY['p3','high_ability','logical','deduction','constraint','seating'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G100', 'logical_reasoning', 'Logical Thinking', '2.2', 'constraint_placement', 'Challenge', 'hard', 'multiple_choice', 'Nora, Orson, Pippa, and Quinn are standing in a line for the water fountain. Nora is 1st in line. Pippa is standing behind Orson. Quinn is standing immediately between Nora and Orson. Who is 4th in line?', '[{"id": "A", "text": "Orson"}, {"id": "B", "text": "Pippa"}, {"id": "C", "text": "Quinn"}, {"id": "D", "text": "Nora"}]'::jsonb, 'B', 'Nora is 1st. Quinn is immediately between Nora and Orson, placing Quinn 2nd and Orson 3rd. Since Pippa is behind Orson, Pippa must be 4th in line. Queue order: 1st:Nora, 2nd:Quinn, 3rd:Orson, 4th:Pippa. So Pippa is 4th in line.', 'Applying multiple spatial and logical constraints to deduce unstated positions.', ARRAY['p3','high_ability','logical','deduction','constraint','seating'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G101', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Think', 'medium', 'multiple_choice', 'Rule: If a number is a multiple of 4, then it is coloured blue. Given: 15 is not blue. What must be true?', '[{"id": "A", "text": "15 is a multiple of 4"}, {"id": "B", "text": "15 is not a multiple of 4"}, {"id": "C", "text": "15 is blue"}, {"id": "D", "text": "15 is an even number"}]'::jsonb, 'B', 'The given rule is: ''a number is a multiple of 4 → it is coloured blue''. We are given that 15 is not blue (the opposite of the conclusion). By the logical rule of contrapositive (if Not Q, then Not P), we can validly conclude that: 15 is not a multiple of 4.', 'Applying the contrapositive deduction rule (If P then Q; Not Q therefore Not P).', ARRAY['p3','high_ability','logical','conditional','contrapositive'], false, NULL, NULL, false);
