INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G119', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Explore', 'easy', 'multiple_choice', 'Rule: If a number is prime and greater than 2, then it must be odd. Given: 17 is a prime number greater than 2. What can we conclude?', '[{"id": "A", "text": "17 must be odd"}, {"id": "B", "text": "17 is divisible by 2"}, {"id": "C", "text": "17 must be even"}, {"id": "D", "text": "17 is not prime"}]'::jsonb, 'A', 'The rule states: ''If a number is prime and greater than 2, then it must be odd''. Since 17 is a prime number greater than 2 satisfies the condition (P is true), by direct deduction (Modus Ponens), the result must follow: 17 must be odd.', 'Applying direct conditional deduction (Modus Ponens: If P then Q; P therefore Q).', ARRAY['p3','high_ability','logical','conditional','deduction'], false, NULL, NULL, false);
