INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G121', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Explore', 'easy', 'multiple_choice', 'Rule: If a figure is a cube, then it has exactly 6 flat faces. Given: Block C is a cube. What can we conclude?', '[{"id": "A", "text": "Block C has exactly 6 flat faces"}, {"id": "B", "text": "Block C has 5 flat faces"}, {"id": "C", "text": "Block C has 8 flat faces"}, {"id": "D", "text": "Block C is not a cube"}]'::jsonb, 'A', 'The rule states: ''If a figure is a cube, then it has exactly 6 flat faces''. Since Block C is a cube satisfies the condition (P is true), by direct deduction (Modus Ponens), the result must follow: Block C has exactly 6 flat faces.', 'Applying direct conditional deduction (Modus Ponens: If P then Q; P therefore Q).', ARRAY['p3','high_ability','logical','conditional','deduction'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G122', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Explore', 'easy', 'multiple_choice', 'Rule: If a number ends in 0, then it is a multiple of 5. Given: The number 80 ends in 0. What can we conclude?', '[{"id": "A", "text": "80 is an odd number"}, {"id": "B", "text": "80 is not a multiple of 5"}, {"id": "C", "text": "80 does not end in 0"}, {"id": "D", "text": "80 is a multiple of 5"}]'::jsonb, 'D', 'The rule states: ''If a number ends in 0, then it is a multiple of 5''. Since The number 80 ends in 0 satisfies the condition (P is true), by direct deduction (Modus Ponens), the result must follow: 80 is a multiple of 5.', 'Applying direct conditional deduction (Modus Ponens: If P then Q; P therefore Q).', ARRAY['p3','high_ability','logical','conditional','deduction'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G123', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Explore', 'easy', 'multiple_choice', 'Rule: If an angle is a right angle, then it measures exactly 90 degrees. Given: Angle K is a right angle. What can we conclude?', '[{"id": "A", "text": "Angle K measures 45 degrees"}, {"id": "B", "text": "Angle K measures exactly 90 degrees"}, {"id": "C", "text": "Angle K measures 180 degrees"}, {"id": "D", "text": "Angle K is not a right angle"}]'::jsonb, 'B', 'The rule states: ''If an angle is a right angle, then it measures exactly 90 degrees''. Since Angle K is a right angle satisfies the condition (P is true), by direct deduction (Modus Ponens), the result must follow: Angle K measures exactly 90 degrees.', 'Applying direct conditional deduction (Modus Ponens: If P then Q; P therefore Q).', ARRAY['p3','high_ability','logical','conditional','deduction'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G124', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Explore', 'easy', 'multiple_choice', 'Rule: If a fruit is a citrus fruit, then it contains citric acid. Given: A lemon is a citrus fruit. What can we conclude?', '[{"id": "A", "text": "A lemon does not contain citric acid"}, {"id": "B", "text": "A lemon contains citric acid"}, {"id": "C", "text": "A lemon is not a fruit"}, {"id": "D", "text": "All fruits are lemons"}]'::jsonb, 'B', 'The rule states: ''If a fruit is a citrus fruit, then it contains citric acid''. Since A lemon is a citrus fruit satisfies the condition (P is true), by direct deduction (Modus Ponens), the result must follow: A lemon contains citric acid.', 'Applying direct conditional deduction (Modus Ponens: If P then Q; P therefore Q).', ARRAY['p3','high_ability','logical','conditional','deduction'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G125', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Explore', 'easy', 'multiple_choice', 'Rule: If a polygon is an octagon, then it has 8 straight sides. Given: Tile T is an octagon. What can we conclude?', '[{"id": "A", "text": "Tile T has 8 straight sides"}, {"id": "B", "text": "Tile T is not an octagon"}, {"id": "C", "text": "Tile T has 6 straight sides"}, {"id": "D", "text": "Tile T has 10 straight sides"}]'::jsonb, 'A', 'The rule states: ''If a polygon is an octagon, then it has 8 straight sides''. Since Tile T is an octagon satisfies the condition (P is true), by direct deduction (Modus Ponens), the result must follow: Tile T has 8 straight sides.', 'Applying direct conditional deduction (Modus Ponens: If P then Q; P therefore Q).', ARRAY['p3','high_ability','logical','conditional','deduction'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G126', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Explore', 'easy', 'multiple_choice', 'If it is sunny on Saturday, Ken goes to the swimming pool. If Ken goes to the swimming pool, he wears his blue goggles. It is sunny on Saturday. What must be true?', '[{"id": "A", "text": "Ken does not go to the pool"}, {"id": "B", "text": "Ken wears his blue goggles"}, {"id": "C", "text": "It is not sunny on Saturday"}, {"id": "D", "text": "Ken wears red goggles"}]'::jsonb, 'B', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''Ken wears his blue goggles''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G127', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If a number is a multiple of 12, it is a multiple of 6. If a number is a multiple of 6, it is an even number. The number 36 is a multiple of 12. What must be true?', '[{"id": "A", "text": "36 is an odd number"}, {"id": "B", "text": "36 is an even number"}, {"id": "C", "text": "36 is not divisible by 3"}, {"id": "D", "text": "36 is not a multiple of 6"}]'::jsonb, 'B', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''36 is an even number''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G128', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If Zoe finishes her homework early, she reads a book. If Zoe reads a book, she learns new vocabulary words. Zoe finishes her homework early today. What must be true?', '[{"id": "A", "text": "Zoe does not read a book"}, {"id": "B", "text": "Zoe learns new vocabulary words"}, {"id": "C", "text": "Zoe watches television"}, {"id": "D", "text": "Zoe does not finish her homework"}]'::jsonb, 'B', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''Zoe learns new vocabulary words''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G129', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If an animal is a robin, it is a bird. If an animal is a bird, it has wings. Chirpy is a robin. What must be true?', '[{"id": "A", "text": "Chirpy has wings"}, {"id": "B", "text": "Chirpy does not have wings"}, {"id": "C", "text": "Chirpy is not a bird"}, {"id": "D", "text": "Chirpy cannot fly"}]'::jsonb, 'A', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''Chirpy has wings''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G130', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If a shape is a square, it is a rectangle. If a shape is a rectangle, it has 4 right angles. Shape S is a square. What must be true?', '[{"id": "A", "text": "Shape S has 3 sides"}, {"id": "B", "text": "Shape S has only 2 right angles"}, {"id": "C", "text": "Shape S is not a rectangle"}, {"id": "D", "text": "Shape S has 4 right angles"}]'::jsonb, 'D', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''Shape S has 4 right angles''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G131', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If a student joins the chess club, they receive a club badge. If a student receives a club badge, they can enter the tournament. Liam joins the chess club. What must be true?', '[{"id": "A", "text": "Liam leaves the chess club"}, {"id": "B", "text": "Liam does not receive a club badge"}, {"id": "C", "text": "Liam cannot enter the tournament"}, {"id": "D", "text": "Liam can enter the tournament"}]'::jsonb, 'D', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''Liam can enter the tournament''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G132', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If a plant receives enough sunlight, it makes food. If a plant makes food, it grows healthy green leaves. Plant A receives enough sunlight. What must be true?', '[{"id": "A", "text": "Plant A receives no sunlight"}, {"id": "B", "text": "Plant A wilts"}, {"id": "C", "text": "Plant A does not make food"}, {"id": "D", "text": "Plant A grows healthy green leaves"}]'::jsonb, 'D', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''Plant A grows healthy green leaves''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G133', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If a number is a multiple of 20, it is a multiple of 10. If a number is a multiple of 10, its last digit is 0. The number 60 is a multiple of 20. What must be true?', '[{"id": "A", "text": "60 has a last digit of 0"}, {"id": "B", "text": "60 is not a multiple of 10"}, {"id": "C", "text": "60 is an odd number"}, {"id": "D", "text": "60 ends in 5"}]'::jsonb, 'A', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''60 has a last digit of 0''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G134', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If David saves $10 this week, he buys a model airplane kit. If David buys a model airplane kit, he builds it on Sunday. David saves $10 this week. What must be true?', '[{"id": "A", "text": "David sells his kit"}, {"id": "B", "text": "David does not buy the kit"}, {"id": "C", "text": "David does not save $10"}, {"id": "D", "text": "David builds the model airplane kit on Sunday"}]'::jsonb, 'D', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''David builds the model airplane kit on Sunday''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G135', 'logical_reasoning', 'Logical Thinking', '2.3', 'conditional_contrapositive', 'Challenge', 'hard', 'multiple_choice', 'If a polygon is a regular hexagon, all 6 of its sides are equal. If all 6 sides are equal, its perimeter is 6 times one side. Shape H is a regular hexagon with side length 3 cm. What must be true?', '[{"id": "A", "text": "Shape H has a perimeter of 18 cm"}, {"id": "B", "text": "Shape H has unequal sides"}, {"id": "C", "text": "Shape H has 5 sides"}, {"id": "D", "text": "Shape H has a perimeter of 12 cm"}]'::jsonb, 'A', 'Following the chain of conditions step by step leads directly to the conclusion. Therefore, the statement that must be true is: ''Shape H has a perimeter of 18 cm''.', 'Applying a transitive conditional reasoning chain (P → Q → R; P therefore R).', ARRAY['p3','high_ability','logical','conditional','transitive_chain'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G136', 'verbal_reasoning', 'Verbal Reasoning', '3.6', 'letter_series', 'Think', 'medium', 'multiple_choice', 'A letter pattern goes: B, D, F, H, ___. Each step moves 2 letters forward (+2). What comes next?', '[{"id": "A", "text": "I"}, {"id": "B", "text": "J"}, {"id": "C", "text": "G"}, {"id": "D", "text": "K"}]'::jsonb, 'B', 'Tracking letter positions: B(2)→D(4) D(4)→F(6) F(6)→H(8). Following the rule, the next step from H(8) applies a shift of +2, yielding position 8 + (+2) = 10 → J.', 'Finding the rule in a letter series and applying the correct next gap position.', ARRAY['p3','high_ability','verbal','letter_pattern','sequence'], false, NULL, NULL, false);
