INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G143', 'verbal_reasoning', 'Verbal Reasoning', '3.6', 'letter_series', 'Think', 'medium', 'multiple_choice', 'A letter pattern goes: P, S, R, U, ___. The gaps alternate between +3 and -1. What comes next?', '[{"id": "A", "text": "X"}, {"id": "B", "text": "T"}, {"id": "C", "text": "V"}, {"id": "D", "text": "U"}]'::jsonb, 'B', 'Tracking letter positions: P(16)→S(19) S(19)→R(18) R(18)→U(21). Following the rule, the next step from U(21) applies a shift of -1, yielding position 21 + (-1) = 20 → T.', 'Finding the rule in a letter series and applying the correct next gap position.', ARRAY['p3','high_ability','verbal','letter_pattern','sequence'], false, NULL, NULL, false);
