INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G156', 'problem_solving', 'Problem Solving', '6.3', 'before_after_transfer', 'Think', 'medium', 'multiple_choice', 'Amy has 24 stickers and Ben has 16 stickers. Amy gives Ben 3 stickers. Now who has more stickers, and by how many?', '[{"id": "A", "text": "Amy, by 2"}, {"id": "B", "text": "They have the same amount"}, {"id": "C", "text": "Ben, by 2"}, {"id": "D", "text": "Amy, by 8"}]'::jsonb, 'A', 'Initially: Amy = 24, Ben = 16 (initial difference = 8). After the transfer: Amy has 21 stickers and Ben has 19 stickers. Comparing the new amounts (21 vs 19), the result is: Amy, by 2.', 'Applying the transfer heuristic: a transfer of N items between two people changes their difference by 2N.', ARRAY['p3','high_ability','problem_solving','before_after','transfer','heuristic'], false, NULL, NULL, false);
