INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G186', 'problem_solving', 'Problem Solving', '6.4', 'draw_diagram_gaps', 'Think', 'medium', 'multiple_choice', '7 fence posts are placed evenly along a straight fence, with a distance of 3 m between every two consecutive fence posts. What is the length of the fence from the first to the last post?', '[{"id": "A", "text": "15 m"}, {"id": "B", "text": "18 m"}, {"id": "C", "text": "24 m"}, {"id": "D", "text": "21 m"}]'::jsonb, 'B', 'Draw a diagram: along a straight line, 7 fence posts create exactly 7 − 1 = 6 equal intervals (gaps). Each gap is 3 m. Total distance = 6 × 3 m = 18 m.', 'Using the ''draw a diagram / count gaps'' heuristic for objects in a line: Gaps = N - 1.', ARRAY['p3','high_ability','problem_solving','draw_diagram','intervals','heuristic'], false, NULL, NULL, false);
