INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G218', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'Mei has 3 shirts (red, blue, green) and 4 pairs of shorts (black, white, grey, navy). How many different outfits of 1 shirt and 1 pair of shorts can she make?', '[{"id": "A", "text": "10"}, {"id": "B", "text": "12"}, {"id": "C", "text": "7"}, {"id": "D", "text": "14"}]'::jsonb, 'B', 'List systematically: Each of the 3 shirts can be paired with any of the 4 shorts. Total = 3 × 4 = 12 outfits.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G219', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'Four friends (Ali, Ben, Cai, and Dan) each shake hands with every other friend exactly once. How many handshakes take place in total?', '[{"id": "A", "text": "4"}, {"id": "B", "text": "12"}, {"id": "C", "text": "6"}, {"id": "D", "text": "8"}]'::jsonb, 'C', 'List pairs systematically: Ali-Ben, Ali-Cai, Ali-Dan (3); Ben-Cai, Ben-Dan (2); Cai-Dan (1). Total = 3 + 2 + 1 = 6 handshakes.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G220', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'How many different 3-letter words (real or made-up) can you form using the letters X, Y, and Z using each letter exactly once?', '[{"id": "A", "text": "27"}, {"id": "B", "text": "3"}, {"id": "C", "text": "6"}, {"id": "D", "text": "9"}]'::jsonb, 'C', 'List systematically: XYZ, XZY, YXZ, YZX, ZXY, ZYX. There are 6 different arrangements.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G221', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'A set meal allows you to choose 1 main dish, 1 drink, and 1 dessert. The menu offers 2 mains, 3 drinks, and 2 desserts. How many different meal combinations can you choose?', '[{"id": "A", "text": "10"}, {"id": "B", "text": "18"}, {"id": "C", "text": "12"}, {"id": "D", "text": "7"}]'::jsonb, 'C', 'Organised counting: Multiply the number of choices for each course: 2 (mains) × 3 (drinks) × 2 (desserts) = 12 combinations.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G222', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'How many different ways can you pay exactly 40 cents using only 10-cent and 20-cent coins?', '[{"id": "A", "text": "5"}, {"id": "B", "text": "2"}, {"id": "C", "text": "3"}, {"id": "D", "text": "4"}]'::jsonb, 'C', 'List combinations systematically by number of 20-cent coins: (1) Two 20¢ coins; (2) One 20¢ and two 10¢ coins; (3) Four 10¢ coins. Total = 3 ways.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G223', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'A teacher wants to choose 2 captains from a group of 5 students (A, B, C, D, E). How many different pairs of captains can be chosen?', '[{"id": "A", "text": "5"}, {"id": "B", "text": "20"}, {"id": "C", "text": "10"}, {"id": "D", "text": "15"}]'::jsonb, 'C', 'List pairs systematically: AB, AC, AD, AE (4); BC, BD, BE (3); CD, CE (2); DE (1). Total = 4 + 3 + 2 + 1 = 10 pairs.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G224', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'How many 2-digit EVEN numbers can be formed using the digits 1, 2, 3, and 4 without repeating any digit?', '[{"id": "A", "text": "6"}, {"id": "B", "text": "4"}, {"id": "C", "text": "12"}, {"id": "D", "text": "8"}]'::jsonb, 'A', 'An even number must end in 2 or 4. If ending in 2: 12, 32, 42 (3 numbers). If ending in 4: 14, 24, 34 (3 numbers). Total = 3 + 3 = 6 even numbers.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G225', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Think', 'medium', 'multiple_choice', 'At a chess club meeting, 5 members each play exactly one game against every other member. How many games are played altogether?', '[{"id": "A", "text": "10"}, {"id": "B", "text": "8"}, {"id": "C", "text": "15"}, {"id": "D", "text": "20"}]'::jsonb, 'A', 'List all pairings systematically: Player 1 plays 4 games; Player 2 plays 3 remaining games; Player 3 plays 2 games; Player 4 plays 1 game. Total = 4 + 3 + 2 + 1 = 10 games.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
