INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G242', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Challenge', 'hard', 'multiple_choice', 'Four books (Math, Science, English, Art) are placed on a shelf in a row. If the Math book must always be on the far left, in how many different orders can all four books be arranged?', '[{"id": "A", "text": "4"}, {"id": "B", "text": "8"}, {"id": "C", "text": "6"}, {"id": "D", "text": "24"}]'::jsonb, 'C', 'The Math book is fixed in position 1. The remaining 3 positions can be filled by Science, English, and Art in 3 × 2 × 1 = 6 different ways.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G243', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Challenge', 'hard', 'multiple_choice', 'A cafeteria lunch menu has 4 main dishes and 3 side dishes. How many different lunches containing 1 main dish and 1 side dish can you choose?', '[{"id": "A", "text": "7"}, {"id": "B", "text": "9"}, {"id": "C", "text": "12"}, {"id": "D", "text": "14"}]'::jsonb, 'C', 'Multiply choices: 4 (mains) × 3 (sides) = 12 different lunch combinations.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G244', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Challenge', 'hard', 'multiple_choice', 'How many 2-digit numbers less than 50 can be formed using the digits 1, 3, 5, and 7 without repeating any digit?', '[{"id": "A", "text": "6"}, {"id": "B", "text": "4"}, {"id": "C", "text": "12"}, {"id": "D", "text": "8"}]'::jsonb, 'A', 'The tens digit must be 1 or 3 (2 choices). For each, there are 3 remaining choices for the ones digit. List: 13, 15, 17, 31, 35, 37. Total = 6 numbers.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G245', 'problem_solving', 'Problem Solving', '6.5', 'make_a_list', 'Challenge', 'hard', 'multiple_choice', 'When rolling two standard 6-sided dice, in how many different ways can the two rolled numbers sum to 8?', '[{"id": "A", "text": "7"}, {"id": "B", "text": "4"}, {"id": "C", "text": "5"}, {"id": "D", "text": "6"}]'::jsonb, 'C', 'List all pairs (Die 1, Die 2): (2,6), (3,5), (4,4), (5,3), (6,2). Total = 5 ways.', 'Using the ''make an organised list'' heuristic to systematically count all valid possibilities.', ARRAY['p3','high_ability','problem_solving','make_a_list','counting','combinatorics','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G246', 'problem_solving', 'Problem Solving', '6.6', 'pattern_application', 'Think', 'medium', 'multiple_choice', 'A number machine changes numbers following a secret rule: 2 → 5, 3 → 7, 4 → 9. If the input is 7, what number comes out?', '[{"id": "A", "text": "14"}, {"id": "B", "text": "13"}, {"id": "C", "text": "16"}, {"id": "D", "text": "15"}]'::jsonb, 'D', 'Discover the rule by testing the examples: 2 follows output = (2 × 2) + 1 = 5, 3 follows output = (3 × 2) + 1 = 7, 4 follows output = (4 × 2) + 1 = 9. The rule is: output = (input × 2) + 1. Applying this rule to the input 7: output = (7 × 2) + 1 = 15.', 'Discovering a functional algebraic/arithmetic rule from input-output examples and applying it to a new value.', ARRAY['p3','high_ability','problem_solving','pattern_application','function_rule','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G247', 'problem_solving', 'Problem Solving', '6.6', 'pattern_application', 'Think', 'medium', 'multiple_choice', 'A magic box changes numbers following a secret rule: 2 → 5, 3 → 8, 4 → 11. If the input is 6, what number comes out?', '[{"id": "A", "text": "15"}, {"id": "B", "text": "17"}, {"id": "C", "text": "16"}, {"id": "D", "text": "18"}]'::jsonb, 'B', 'Discover the rule by testing the examples: 2 follows output = (2 × 3) − 1 = 5, 3 follows output = (3 × 3) − 1 = 8, 4 follows output = (4 × 3) − 1 = 11. The rule is: output = (input × 3) − 1. Applying this rule to the input 6: output = (6 × 3) − 1 = 17.', 'Discovering a functional algebraic/arithmetic rule from input-output examples and applying it to a new value.', ARRAY['p3','high_ability','problem_solving','pattern_application','function_rule','heuristic'], false, NULL, NULL, false);
