INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G266', 'problem_solving', 'Problem Solving', '6.6', 'pattern_application', 'Explore', 'easy', 'multiple_choice', 'A number machine changes numbers following a secret rule: 2 → 2, 3 → 6, 4 → 12. If the input is 6, what number comes out?', '[{"id": "A", "text": "28"}, {"id": "B", "text": "30"}, {"id": "C", "text": "36"}, {"id": "D", "text": "24"}]'::jsonb, 'B', 'Discover the rule by testing the examples: 2 follows output = 2 × (2 − 1) = 2, 3 follows output = 3 × (3 − 1) = 6, 4 follows output = 4 × (4 − 1) = 12. The rule is: output = input × (input − 1). Applying this rule to the input 6: output = 6 × (6 − 1) = 30.', 'Discovering a functional algebraic/arithmetic rule from input-output examples and applying it to a new value.', ARRAY['p3','high_ability','problem_solving','pattern_application','function_rule','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G267', 'problem_solving', 'Problem Solving', '6.6', 'pattern_application', 'Explore', 'easy', 'multiple_choice', 'A magic box changes numbers following a secret rule: 1 → 4, 2 → 9, 3 → 16. If the input is 4, what number comes out?', '[{"id": "A", "text": "20"}, {"id": "B", "text": "26"}, {"id": "C", "text": "25"}, {"id": "D", "text": "24"}]'::jsonb, 'C', 'Discover the rule by testing the examples: 1 follows output = (1 + 1) × (1 + 1) = 4, 2 follows output = (2 + 1) × (2 + 1) = 9, 3 follows output = (3 + 1) × (3 + 1) = 16. The rule is: output = (input + 1) × (input + 1). Applying this rule to the input 4: output = (4 + 1) × (4 + 1) = 25.', 'Discovering a functional algebraic/arithmetic rule from input-output examples and applying it to a new value.', ARRAY['p3','high_ability','problem_solving','pattern_application','function_rule','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G268', 'problem_solving', 'Problem Solving', '6.6', 'pattern_application', 'Explore', 'easy', 'multiple_choice', 'A number pattern machine changes numbers following a secret rule: 2 → 7, 3 → 11, 4 → 15. If the input is 6, what number comes out?', '[{"id": "A", "text": "24"}, {"id": "B", "text": "25"}, {"id": "C", "text": "22"}, {"id": "D", "text": "23"}]'::jsonb, 'D', 'Discover the rule by testing the examples: 2 follows output = (2 × 4) − 1 = 7, 3 follows output = (3 × 4) − 1 = 11, 4 follows output = (4 × 4) − 1 = 15. The rule is: output = (input × 4) − 1. Applying this rule to the input 6: output = (6 × 4) − 1 = 23.', 'Discovering a functional algebraic/arithmetic rule from input-output examples and applying it to a new value.', ARRAY['p3','high_ability','problem_solving','pattern_application','function_rule','heuristic'], false, NULL, NULL, false);
INSERT INTO public.brainactive_questions (id, domain, topic, skill, archetype, level, difficulty, question_type, question, options, answer, explanation, reasoning, tags, visual_required, visual_spec, image_path, is_active) VALUES ('BA_P3_G269', 'problem_solving', 'Problem Solving', '6.6', 'pattern_application', 'Challenge', 'hard', 'multiple_choice', 'A math robot changes numbers following a secret rule: 1 → 7, 2 → 10, 3 → 13. If the input is 5, what number comes out?', '[{"id": "A", "text": "18"}, {"id": "B", "text": "17"}, {"id": "C", "text": "20"}, {"id": "D", "text": "19"}]'::jsonb, 'D', 'Discover the rule by testing the examples: 1 follows output = (1 × 3) + 4 = 7, 2 follows output = (2 × 3) + 4 = 10, 3 follows output = (3 × 3) + 4 = 13. The rule is: output = (input × 3) + 4. Applying this rule to the input 5: output = (5 × 3) + 4 = 19.', 'Discovering a functional algebraic/arithmetic rule from input-output examples and applying it to a new value.', ARRAY['p3','high_ability','problem_solving','pattern_application','function_rule','heuristic'], false, NULL, NULL, false);
